import {
  BOSS_ORDER,
  ENEMIES,
  EVENT_BY_ID,
  HERO_CLASSES,
  RULES,
  RULE_BY_ID,
  RUN_EVENTS,
  getBossEnemyId,
  getHeroClass,
} from "../content/gameContent";
import { clamp } from "./math";
import { hashString, SeededRng } from "./rng";
import type {
  BossId,
  EncounterDefinition,
  EventChoice,
  HeroClassId,
  MetaProgress,
  RewardOption,
  RoomType,
  RuleDefinition,
  RuleId,
  RuleInstance,
  RuleRarity,
  RunEventDefinition,
  RunMapBranchPreview,
  RunMapNode,
  RunState,
  ShopOffer,
} from "./types";

const RARITY_WEIGHT: Record<RuleRarity, number> = {
  common: 58,
  uncommon: 28,
  rare: 11,
  legendary: 3,
};

const RARITY_PRICE: Record<RuleRarity, number> = {
  common: 55,
  uncommon: 85,
  rare: 130,
  legendary: 210,
};

const THEMES = ["crypt", "ash", "frost", "ink", "throne"] as const;

export function createDefaultMeta(): MetaProgress {
  const starterRules = getHeroClass("penitent").startingRules;
  return {
    version: 1,
    unlockedClassIds: ["penitent"],
    unlockedRuleIds: [...new Set(starterRules)],
    discoveredRuleIds: [...new Set(starterRules)],
    victories: 0,
    highestDifficulty: 0,
    totalRuns: 0,
    totalBossesKilled: 0,
    achievements: [],
  };
}

export function createRun(seed: number, classId: HeroClassId, difficulty = 0): RunState {
  const heroClass = getHeroClass(classId);
  const ownedRules: RuleInstance[] = heroClass.startingRules.map((ruleId, index) => ({
    ruleId,
    level: 1,
    acquiredAt: index,
  }));
  const now = Date.now();
  const run: RunState = {
    version: 1,
    seed,
    classId,
    chapter: 1,
    depth: 0,
    difficulty,
    routeKey: initialRouteKey(seed),
    currentHealth: heroClass.maxHealth,
    maxHealthBonus: 0,
    damageBonusPct: 0,
    shield: 0,
    gold: 45,
    ink: heroClass.startingInk,
    maxInk: heroClass.maxInk,
    rewriteCostMultiplierPct: heroClass.passive === "scribe" ? 75 : 100,
    slotCount: heroClass.startingSlots,
    ownedRules,
    activeRuleIds: heroClass.startingRules.slice(0, heroClass.startingSlots),
    availableNodes: [],
    pendingRewardRuleIds: [],
    discoveredRuleIds: [...heroClass.startingRules],
    completedBossIds: [],
    statistics: {
      roomsCleared: 0,
      enemiesKilled: 0,
      elitesKilled: 0,
      bossesKilled: 0,
      rulesTriggered: 0,
      rewritesUsed: 0,
      damageDealt: 0,
      damageTaken: 0,
      healingReceived: 0,
      goldEarned: 0,
      longestChain: 0,
    },
    startedAt: now,
    updatedAt: now,
  };
  run.availableNodes = generateNodes(run);
  return run;
}

export function generateNodes(run: RunState): RunMapNode[] {
  return generateNodesFor(run, run.chapter, run.depth, normalizeRouteKey(run));
}

export function generateBranchPreviews(run: RunState): RunMapBranchPreview[] {
  return run.availableNodes.map((node) => ({
    sourceNodeId: node.id,
    nextNodes: previewNodesAfterChoice(run, node),
  }));
}

export function previewNodesAfterChoice(run: RunState, node: RunMapNode): RunMapNode[] {
  const nextRouteKey = advanceRouteKey(normalizeRouteKey(run), node.id);
  if (node.type === "boss") {
    if (run.chapter >= BOSS_ORDER.length) return [];
    return generateNodesFor(run, run.chapter + 1, 0, nextRouteKey);
  }
  return generateNodesFor(run, run.chapter, run.depth + 1, nextRouteKey);
}

function generateNodesFor(run: RunState, chapter: number, depth: number, routeKey: number): RunMapNode[] {
  const rng = new SeededRng(run.seed ^ routeKey ^ hashString(`${chapter}:${depth}:nodes`));
  const bossId = BOSS_ORDER[chapter - 1];
  const routeSignature = routeKey.toString(16).padStart(8, "0").slice(-8);
  if (depth >= 5) {
    if (!bossId) return [];
    return [
      {
        id: `c${chapter}-d${depth}-r${routeSignature}-boss`,
        chapter,
        depth,
        type: "boss",
        title: bossTitle(bossId),
        subtitle: bossSubtitle(bossId),
        danger: 5 + chapter + run.difficulty,
        completed: false,
        bossId,
      },
    ];
  }

  const candidateTypes: RoomType[] =
    depth === 4
      ? ["elite", "sanctuary", "shop"]
      : rng.shuffle<RoomType>(["combat", "combat", "event", "shop", "sanctuary", "combat"]).slice(0, 3);
  const unique = [...new Set(candidateTypes)];
  while (unique.length < 3)
    unique.push(unique.length === 0 ? "combat" : unique.length === 1 ? "event" : "shop");

  return unique.slice(0, 3).map((type, index) => ({
    id: `c${chapter}-d${depth}-r${routeSignature}-${index}-${type}`,
    chapter,
    depth,
    type,
    title: roomTitle(type),
    subtitle: roomSubtitle(type, chapter, depth),
    danger: Math.max(1, chapter + Math.floor(depth / 2) + (type === "elite" ? 2 : 0) + run.difficulty),
    completed: false,
  }));
}

export function buildEncounter(run: RunState, node: RunMapNode): EncounterDefinition {
  if (node.type !== "combat" && node.type !== "elite" && node.type !== "boss") {
    throw new Error(`Le nœud ${node.id} n'est pas un combat`);
  }
  const rng = new SeededRng(run.seed ^ hashString(node.id));
  const theme = THEMES[Math.min(THEMES.length - 1, run.chapter - 1)] ?? "crypt";
  if (node.type === "boss") {
    const bossId = node.bossId ?? BOSS_ORDER[run.chapter - 1];
    if (!bossId) throw new Error("Boss introuvable");
    const supportPool = unlockedEnemyPool(run.chapter).filter((id) => id !== "chain-guardian");
    const support = run.chapter >= 2 ? rng.pick(supportPool) : "fanatic";
    return {
      id: node.id,
      name: bossTitle(bossId),
      chapter: run.chapter,
      roomType: "boss",
      arenaTheme: theme,
      enemies: [
        { definitionId: getBossEnemyId(bossId), level: run.chapter + run.difficulty, count: 1 },
        {
          definitionId: support,
          level: Math.max(1, run.chapter - 1 + run.difficulty),
          count: Math.min(3, run.chapter - 1),
        },
      ].filter((spec) => spec.count > 0),
      rewardTier: 4,
      bossId,
    };
  }

  if (node.type === "elite") {
    const pool = unlockedEnemyPool(run.chapter);
    return {
      id: node.id,
      name: "La Chambre du Censeur",
      chapter: run.chapter,
      roomType: "elite",
      arenaTheme: theme,
      enemies: [
        { definitionId: "censor-elite", level: run.chapter + run.difficulty, count: 1 },
        {
          definitionId: rng.pick(pool),
          level: run.chapter + run.difficulty,
          count: 2 + Math.floor(run.chapter / 2),
        },
      ],
      rewardTier: 3,
    };
  }

  const pool = unlockedEnemyPool(run.chapter);
  const first = rng.pick(pool);
  const second = rng.pick(
    pool.filter((id) => id !== first).length > 0 ? pool.filter((id) => id !== first) : pool,
  );
  const baseCount = 3 + run.chapter + Math.floor(run.depth / 2) + run.difficulty;
  const firstCount = Math.ceil(baseCount * 0.6);
  return {
    id: node.id,
    name: `Affrontement — ${roomSubtitle("combat", run.chapter, run.depth)}`,
    chapter: run.chapter,
    roomType: "combat",
    arenaTheme: theme,
    enemies: [
      { definitionId: first, level: run.chapter + run.difficulty, count: firstCount },
      {
        definitionId: second,
        level: run.chapter + run.difficulty,
        count: Math.max(1, baseCount - firstCount),
      },
    ],
    rewardTier: run.depth >= 3 ? 2 : 1,
  };
}

export function generateRewardOptions(run: RunState, tier: number): RewardOption[] {
  const rng = new SeededRng(
    run.seed ^ hashString(`${run.chapter}:${run.depth}:reward:${run.statistics.roomsCleared}`),
  );
  const owned = new Set(run.ownedRules.map((entry) => entry.ruleId));
  const eligible = RULES.filter((entry) => !owned.has(entry.id));
  const options: RewardOption[] = [];
  const candidates = rng
    .shuffle(eligible)
    .sort((a, b) => adjustedRarityWeight(b, tier) - adjustedRarityWeight(a, tier));

  for (const definition of candidates) {
    if (options.length >= 3) break;
    if (!rng.chance(Math.min(92, adjustedRarityWeight(definition, tier) + 22))) continue;
    options.push({
      id: `rule-${definition.id}`,
      kind: "rule",
      title: definition.name,
      description: definition.description,
      ruleId: definition.id,
    });
  }

  while (options.length < 3) {
    const fallback = rng.pick<RewardOption>([
      {
        id: `heal-${options.length}`,
        kind: "heal",
        title: "Réparation du Pénitent",
        description: "Récupérer 35 % de vie.",
      },
      {
        id: `ink-${options.length}`,
        kind: "ink",
        title: "Fiole d’Encre",
        description: "Récupérer 45 Encre du Néant.",
      },
      {
        id: `upgrade-${options.length}`,
        kind: "upgrade",
        title: "Enluminure",
        description: "Améliorer une règle aléatoire du Codex.",
      },
    ]);
    options.push(fallback);
  }

  if (tier >= 4 && run.slotCount < 6) {
    options[0] = {
      id: "slot",
      kind: "slot",
      title: "Page Reliée",
      description: "Ajouter définitivement un emplacement au Codex.",
    };
  }
  return options;
}

export function applyReward(run: RunState, option: RewardOption): void {
  if (option.kind === "rule" && option.ruleId) addRule(run, option.ruleId);
  if (option.kind === "heal") healRun(run, 35);
  if (option.kind === "ink") run.ink = Math.min(run.maxInk, run.ink + 45);
  if (option.kind === "slot") run.slotCount = Math.min(6, run.slotCount + 1);
  if (option.kind === "upgrade")
    upgradeRandomRule(run, new SeededRng(run.seed ^ hashString(option.id + run.statistics.roomsCleared)));
  run.pendingRewardRuleIds = [];
  run.updatedAt = Date.now();
}

export function generateShopOffers(run: RunState): ShopOffer[] {
  const rng = new SeededRng(run.seed ^ hashString(`${run.chapter}:${run.depth}:shop`));
  const owned = new Set(run.ownedRules.map((entry) => entry.ruleId));
  const rules = rng.shuffle(RULES.filter((entry) => !owned.has(entry.id))).slice(0, 3);
  const offers: ShopOffer[] = rules.map((definition, index) => ({
    id: `shop-rule-${index}-${definition.id}`,
    kind: "rule",
    title: definition.name,
    description: definition.description,
    price: RARITY_PRICE[definition.rarity] + run.chapter * 8,
    ruleId: definition.id,
    sold: false,
  }));
  offers.push({
    id: "shop-heal",
    kind: "heal",
    title: "Suture d’Encre",
    description: "Soigne 45 % de la vie maximale.",
    price: 42 + run.chapter * 5,
    sold: false,
  });
  offers.push({
    id: "shop-ink",
    kind: "ink",
    title: "Réserve du Néant",
    description: "Restaure toute l’Encre.",
    price: 36 + run.chapter * 4,
    sold: false,
  });
  offers.push({
    id: "shop-upgrade",
    kind: "upgrade",
    title: "Enluminure forcée",
    description: "Améliore une règle aléatoire.",
    price: 90 + run.chapter * 12,
    sold: false,
  });
  if (run.slotCount < 6)
    offers.push({
      id: "shop-slot",
      kind: "slot",
      title: "Page supplémentaire",
      description: "Ajoute un emplacement au Codex.",
      price: 165 + run.slotCount * 35,
      sold: false,
    });
  return offers;
}

export function buyShopOffer(run: RunState, offer: ShopOffer): boolean {
  if (offer.sold || run.gold < offer.price) return false;
  run.gold -= offer.price;
  if (offer.kind === "rule" && offer.ruleId) addRule(run, offer.ruleId);
  if (offer.kind === "heal") healRun(run, 45);
  if (offer.kind === "ink") run.ink = run.maxInk;
  if (offer.kind === "upgrade") upgradeRandomRule(run, new SeededRng(run.seed ^ hashString(offer.id)));
  if (offer.kind === "slot") run.slotCount = Math.min(6, run.slotCount + 1);
  offer.sold = true;
  run.updatedAt = Date.now();
  return true;
}

export function chooseRunEvent(run: RunState): RunEventDefinition {
  const rng = new SeededRng(run.seed ^ hashString(`${run.chapter}:${run.depth}:event`));
  return rng.pick(RUN_EVENTS);
}

export function applyEventChoice(
  run: RunState,
  eventId: string,
  choice: EventChoice,
): { success: boolean; rewardRuleId?: RuleId } {
  if (!EVENT_BY_ID.has(eventId)) return { success: false };
  if ((choice.costGold ?? 0) > run.gold) return { success: false };
  run.gold -= choice.costGold ?? 0;
  if (choice.healthCostPct) {
    const maxHealth = getRunMaxHealth(run);
    run.currentHealth = Math.max(1, run.currentHealth - Math.ceil((maxHealth * choice.healthCostPct) / 100));
  }
  if (choice.rewardGold) {
    run.gold += choice.rewardGold;
    run.statistics.goldEarned += choice.rewardGold;
  }
  if (choice.healPct) healRun(run, choice.healPct);
  if (choice.gainInk) run.ink = Math.min(run.maxInk, run.ink + choice.gainInk);
  if (choice.addMaxHealth) {
    run.maxHealthBonus += choice.addMaxHealth;
    run.currentHealth += choice.addMaxHealth;
  }
  if (choice.upgradeRandomRule)
    upgradeRandomRule(run, new SeededRng(run.seed ^ hashString(choice.id + eventId)));
  let rewardRuleId: RuleId | undefined;
  if (choice.gainRuleRarity) {
    const candidate = pickRuleByRarity(
      run,
      choice.gainRuleRarity,
      new SeededRng(run.seed ^ hashString(eventId + choice.id)),
    );
    if (candidate) {
      addRule(run, candidate.id);
      rewardRuleId = candidate.id;
    }
  }
  run.updatedAt = Date.now();
  return { success: true, rewardRuleId };
}

export function applySanctuaryAction(
  run: RunState,
  action: "heal" | "upgrade" | "purge" | "ink",
  ruleId?: RuleId,
): boolean {
  if (action === "heal") healRun(run, 65);
  if (action === "ink") run.ink = run.maxInk;
  if (action === "upgrade")
    upgradeRandomRule(run, new SeededRng(run.seed ^ hashString(`sanctuary:${run.chapter}:${run.depth}`)));
  if (action === "purge") {
    if (!ruleId || run.ownedRules.length <= 1) return false;
    run.ownedRules = run.ownedRules.filter((entry) => entry.ruleId !== ruleId);
    run.activeRuleIds = run.activeRuleIds.filter((id) => id !== ruleId);
  }
  run.updatedAt = Date.now();
  return true;
}

export function finishRoom(run: RunState): "continue" | "victory" {
  const node = run.currentNode;
  if (!node) return "continue";
  node.completed = true;
  run.routeKey = advanceRouteKey(normalizeRouteKey(run), node.id);
  run.statistics.roomsCleared += 1;
  if (node.type === "boss" && node.bossId) {
    if (!run.completedBossIds.includes(node.bossId)) run.completedBossIds.push(node.bossId);
    run.statistics.bossesKilled += 1;
    if (run.chapter >= BOSS_ORDER.length) {
      run.currentNode = undefined;
      run.availableNodes = [];
      run.updatedAt = Date.now();
      return "victory";
    }
    run.chapter += 1;
    run.depth = 0;
  } else {
    run.depth += 1;
  }
  run.currentNode = undefined;
  run.availableNodes = generateNodes(run);
  run.updatedAt = Date.now();
  return "continue";
}

export function getRunMaxHealth(run: RunState): number {
  return getHeroClass(run.classId).maxHealth + run.maxHealthBonus;
}

export function setCodexOrder(run: RunState, ruleIds: RuleId[]): boolean {
  if (ruleIds.length < 1 || ruleIds.length > run.slotCount) return false;
  const owned = new Set(run.ownedRules.map((entry) => entry.ruleId));
  if (new Set(ruleIds).size !== ruleIds.length || ruleIds.some((id) => !owned.has(id))) return false;
  run.activeRuleIds = [...ruleIds];
  run.updatedAt = Date.now();
  return true;
}

export function activateRule(run: RunState, ruleId: RuleId): boolean {
  if (run.activeRuleIds.includes(ruleId) || run.activeRuleIds.length >= run.slotCount) return false;
  if (!run.ownedRules.some((entry) => entry.ruleId === ruleId)) return false;
  run.activeRuleIds.push(ruleId);
  run.updatedAt = Date.now();
  return true;
}

export function deactivateRule(run: RunState, ruleId: RuleId): boolean {
  if (run.activeRuleIds.length <= 1) return false;
  run.activeRuleIds = run.activeRuleIds.filter((id) => id !== ruleId);
  run.updatedAt = Date.now();
  return true;
}

export function addRule(run: RunState, ruleId: RuleId): void {
  if (!RULE_BY_ID.has(ruleId)) return;
  const existing = run.ownedRules.find((entry) => entry.ruleId === ruleId);
  if (existing) {
    const definition = RULE_BY_ID.get(ruleId);
    existing.level = Math.min(definition?.maxLevel ?? existing.level, existing.level + 1);
  } else {
    run.ownedRules.push({ ruleId, level: 1, acquiredAt: run.statistics.roomsCleared });
    if (run.activeRuleIds.length < run.slotCount) run.activeRuleIds.push(ruleId);
  }
  if (!run.discoveredRuleIds.includes(ruleId)) run.discoveredRuleIds.push(ruleId);
}

export function recordCombatResult(
  run: RunState,
  result: {
    heroHealth: number;
    heroShield: number;
    ink: number;
    goldEarned: number;
    enemiesKilled: number;
    elitesKilled: number;
    rulesTriggered: number;
    rewritesUsed: number;
    damageDealt: number;
    damageTaken: number;
    healingReceived: number;
    longestChain: number;
  },
): void {
  run.currentHealth = Math.max(0, Math.round(result.heroHealth));
  run.shield = Math.max(0, Math.round(result.heroShield));
  run.ink = clamp(Math.round(result.ink), 0, run.maxInk);
  run.gold += result.goldEarned;
  run.statistics.enemiesKilled += result.enemiesKilled;
  run.statistics.elitesKilled += result.elitesKilled;
  run.statistics.rulesTriggered += result.rulesTriggered;
  run.statistics.rewritesUsed += result.rewritesUsed;
  run.statistics.damageDealt += result.damageDealt;
  run.statistics.damageTaken += result.damageTaken;
  run.statistics.healingReceived += result.healingReceived;
  run.statistics.goldEarned += result.goldEarned;
  run.statistics.longestChain = Math.max(run.statistics.longestChain, result.longestChain);
  run.updatedAt = Date.now();
}

export function updateMetaAfterRun(meta: MetaProgress, run: RunState, victory: boolean): void {
  meta.totalRuns += 1;
  meta.totalBossesKilled += run.statistics.bossesKilled;
  meta.highestDifficulty = Math.max(meta.highestDifficulty, run.difficulty);
  meta.discoveredRuleIds = [...new Set([...meta.discoveredRuleIds, ...run.discoveredRuleIds])];
  meta.unlockedRuleIds = [...new Set([...meta.unlockedRuleIds, ...run.discoveredRuleIds])];
  if (run.completedBossIds.includes("bibliophage") && !meta.unlockedClassIds.includes("widow"))
    meta.unlockedClassIds.push("widow");
  if (run.completedBossIds.includes("inverted-king") && !meta.unlockedClassIds.includes("ash-bearer"))
    meta.unlockedClassIds.push("ash-bearer");
  if (victory) {
    meta.victories += 1;
    if (!meta.unlockedClassIds.includes("void-scribe")) meta.unlockedClassIds.push("void-scribe");
    if (!meta.achievements.includes("author-defeated")) meta.achievements.push("author-defeated");
  }
}

function initialRouteKey(seed: number): number {
  return hashString(`${seed >>> 0}:route:origin`) >>> 0;
}

function normalizeRouteKey(run: Pick<RunState, "seed" | "routeKey">): number {
  return Number.isInteger(run.routeKey) ? run.routeKey >>> 0 : initialRouteKey(run.seed);
}

function advanceRouteKey(routeKey: number, nodeId: string): number {
  return hashString(`${routeKey >>> 0}:${nodeId}:next`) >>> 0;
}

function unlockedEnemyPool(chapter: number): string[] {
  const ids = ["fanatic", "crawling-shadow"];
  if (chapter >= 2) ids.push("ink-bearer");
  if (chapter >= 3) ids.push("chain-guardian");
  if (chapter >= 4) ids.push("void-cantor");
  if (chapter >= 5) ids.push("grave-leech");
  return ids.filter((id) => ENEMIES.some((enemy) => enemy.id === id));
}

function adjustedRarityWeight(definition: RuleDefinition, tier: number): number {
  const base = RARITY_WEIGHT[definition.rarity];
  if (definition.rarity === "rare") return base + tier * 8;
  if (definition.rarity === "legendary") return base + tier * 4;
  if (definition.rarity === "common") return Math.max(12, base - tier * 8);
  return base + tier * 2;
}

function pickRuleByRarity(run: RunState, rarity: RuleRarity, rng: SeededRng): RuleDefinition | undefined {
  const owned = new Set(run.ownedRules.map((entry) => entry.ruleId));
  const exact = RULES.filter((entry) => entry.rarity === rarity && !owned.has(entry.id));
  const fallback = RULES.filter((entry) => !owned.has(entry.id));
  const pool = exact.length > 0 ? exact : fallback;
  return pool.length > 0 ? rng.pick(pool) : undefined;
}

function upgradeRandomRule(run: RunState, rng: SeededRng): void {
  const upgradeable = run.ownedRules.filter(
    (entry) => entry.level < (RULE_BY_ID.get(entry.ruleId)?.maxLevel ?? entry.level),
  );
  if (upgradeable.length === 0) {
    run.damageBonusPct += 5;
    return;
  }
  const chosen = rng.pick(upgradeable);
  chosen.level += 1;
}

function healRun(run: RunState, percent: number): void {
  const maxHealth = getRunMaxHealth(run);
  run.currentHealth = Math.min(maxHealth, run.currentHealth + Math.ceil((maxHealth * percent) / 100));
}

function roomTitle(type: RoomType): string {
  switch (type) {
    case "combat":
      return "Salle de combat";
    case "elite":
      return "Sentence du Censeur";
    case "event":
      return "Annotation vivante";
    case "shop":
      return "Échoppe du Relieur";
    case "sanctuary":
      return "Sanctuaire muet";
    case "boss":
      return "Boss";
  }
}

function roomSubtitle(type: RoomType, chapter: number, depth: number): string {
  const chapterNames = [
    "Les Couloirs des Péchés",
    "La Bibliothèque Dévorée",
    "La Couronne Renversée",
    "Le Tribunal Aveugle",
    "La Page Ultime",
  ];
  const chapterName = chapterNames[chapter - 1] ?? `Chapitre ${chapter}`;
  if (type === "combat") return `${chapterName} — affrontement ${depth + 1}`;
  if (type === "elite") return "Une loi sera censurée pendant le combat";
  if (type === "event") return "Un choix irréversible";
  if (type === "shop") return "Dépenser l’or avant qu’il ne vous dépense";
  if (type === "sanctuary") return "Soigner, purifier ou renforcer le Codex";
  return chapterName;
}

function bossTitle(id: BossId): string {
  const names: Record<BossId, string> = {
    inquisitor: "L’Inquisiteur",
    bibliophage: "Le Bibliophage",
    "inverted-king": "Le Roi Inversé",
    "faceless-judge": "Le Juge Sans Visage",
    author: "L’Auteur",
  };
  return names[id];
}

function bossSubtitle(id: BossId): string {
  const subtitles: Record<BossId, string> = {
    inquisitor: "Il condamne la règle qui se déclenche le plus.",
    bibliophage: "Il dévore les derniers emplacements du Codex.",
    "inverted-king": "Il résout les règles de droite à gauche.",
    "faceless-judge": "Il copie votre première loi contre vous.",
    author: "Il change les mots et les cibles de vos lois.",
  };
  return subtitles[id];
}

export function allClassIds(): HeroClassId[] {
  return HERO_CLASSES.map((entry) => entry.id);
}
