function CodexScreen({ snapshot }: { snapshot: RuntimeSnapshot }): React.JSX.Element | null {
  const runtime = useGameStore((state) => state.runtime);
  const run = snapshot.run;
  if (!run) return null;
  const activeSet = new Set(run.activeRuleIds);
  const ownedById = new Map(run.ownedRules.map((entry) => [entry.ruleId, entry]));
  return (
    <section className="screen page-screen codex-screen">
      <ScreenHeader
        title="Le Codex"
        subtitle={`Les règles sont résolues de gauche à droite. ${run.activeRuleIds.length}/${run.slotCount} emplacements utilisés.`}
        onBack={() => runtime?.closeOverlayScreen()}
      />
      <div className="codex-book">
        <section className="codex-page active-page">
          <h2>Chaîne active</h2>
          <p>
            Déplacez une carte : le même ensemble de lois peut produire un résultat entièrement différent.
          </p>
          <div className="codex-active-list">
            {run.activeRuleIds.map((ruleId, index) => {
              const definition = snapshot.ruleDefinitions.find((entry) => entry.id === ruleId);
              const instance = ownedById.get(ruleId);
              if (!definition || !instance) return null;
              return (
                <div className="codex-active-entry" key={ruleId}>
                  <span className="order-number">{index + 1}</span>
                  <RuleCard definition={definition} level={instance.level} index={index} />
                  <div className="vertical-actions">
                    <button
                      type="button"
                      onClick={() => runtime?.moveActiveRule(index, -1)}
                      disabled={index === 0}
                      aria-label="Déplacer à gauche"
                    >
                      ←
                    </button>
                    <button
                      type="button"
                      onClick={() => runtime?.moveActiveRule(index, 1)}
                      disabled={index === run.activeRuleIds.length - 1}
                      aria-label="Déplacer à droite"
                    >
                      →
                    </button>
                    <button
                      type="button"
                      onClick={() => runtime?.deactivateRule(ruleId)}
                      disabled={run.activeRuleIds.length <= 1}
                      aria-label="Retirer"
                    >
                      −
                    </button>
                  </div>
                </div>
              );
            })}
            {Array.from({ length: Math.max(0, run.slotCount - run.activeRuleIds.length) }, (_, index) => (
              <div className="empty-rule-slot" key={`empty-${index}`}>
                Page vide
              </div>
            ))}
          </div>
        </section>
        <section className="codex-page reserve-page">
          <h2>Réserve de règles</h2>
          <div className="reserve-grid">
            {run.ownedRules
              .filter((entry) => !activeSet.has(entry.ruleId))
              .map((instance) => {
                const definition = snapshot.ruleDefinitions.find((entry) => entry.id === instance.ruleId);
                if (!definition) return null;
                return (
                  <div className="reserve-entry" key={instance.ruleId}>
                    <RuleCard definition={definition} level={instance.level} />
                    <button
                      type="button"
                      onClick={() => runtime?.activateRule(instance.ruleId)}
                      disabled={run.activeRuleIds.length >= run.slotCount}
                    >
                      Ajouter à la chaîne
                    </button>
                  </div>
                );
              })}
            {run.ownedRules.filter((entry) => !activeSet.has(entry.ruleId)).length === 0 && (
              <p className="empty-state">Aucune règle en réserve.</p>
            )}
          </div>
        </section>
      </div>
    </section>
  );
}

function Encyclopedia({ snapshot }: { snapshot: RuntimeSnapshot }): React.JSX.Element {
  const runtime = useGameStore((state) => state.runtime);
  const [family, setFamily] = useState<RuleFamily | "all">("all");
  const [query, setQuery] = useState("");
  const discovered = new Set(snapshot.meta.discoveredRuleIds);
  const filtered = snapshot.ruleDefinitions.filter(
    (rule) =>
      (family === "all" || rule.family === family) &&
      `${rule.name} ${rule.description} ${rule.tags.join(" ")}`.toLowerCase().includes(query.toLowerCase()),
  );
  return (
    <section className="screen page-screen encyclopedia-screen">
      <ScreenHeader
        title="Encyclopédie des lois"
        subtitle={`${discovered.size}/${snapshot.ruleDefinitions.length} lois découvertes entre les marches.`}
        onBack={() => runtime?.closeOverlayScreen()}
      />
      <div className="filter-bar">
        <input
          type="search"
          placeholder="Rechercher une interaction…"
          value={query}
          onChange={(event) => setQuery(event.target.value)}
        />
        <select value={family} onChange={(event) => setFamily(event.target.value as RuleFamily | "all")}>
          <option value="all">Toutes les familles</option>
          {Object.entries(FAMILY_LABELS).map(([id, label]) => (
            <option value={id} key={id}>
              {label}
            </option>
          ))}
        </select>
      </div>
      <div className="encyclopedia-grid">
        {filtered.map((definition) => {
          const known = discovered.has(definition.id);
          return known ? (
            <RuleCard key={definition.id} definition={definition} level={1} />
          ) : (
            <div className="unknown-rule" key={definition.id}>
              <span>?</span>
              <strong>Loi non découverte</strong>
              <small>Elle apparaîtra dans une récompense, une boutique ou un événement.</small>
            </div>
          );
        })}
      </div>
    </section>
  );
}

