import {
  ArcRotateCamera,
  Color3,
  Color4,
  DefaultRenderingPipeline,
  DirectionalLight,
  Engine,
  GlowLayer,
  HemisphericLight,
  Mesh,
  MeshBuilder,
  PointLight,
  Scene,
  ShadowGenerator,
  StandardMaterial,
  TransformNode,
  Vector3
} from "@babylonjs/core";
import type {
  ActorSnapshot,
  ArenaTheme,
  CombatSnapshot,
  EventEnvelope,
  GameSettings,
  StatusKind
} from "../../domain/types";
import { AssetRegistry } from "./AssetRegistry";
import { VfxSystem } from "./VfxSystem";

interface ActorView {
  root: TransformNode;
  parts: Mesh[];
  primaryMaterial: StandardMaterial;
  accentMaterial: StandardMaterial;
  ring: Mesh;
  ringMaterial: StandardMaterial;
  targetPosition: Vector3;
  baseY: number;
  phaseOffset: number;
  modelRequested: boolean;
}

interface ThemePalette {
  ground: Color3;
  accent: Color3;
  fog: Color3;
  light: Color3;
}

const STATUS_COLORS: Record<StatusKind, Color3> = {
  burn: new Color3(1, 0.24, 0.025),
  poison: new Color3(0.32, 1, 0.2),
  freeze: new Color3(0.25, 0.78, 1),
  haste: new Color3(1, 0.82, 0.24),
  weakness: new Color3(0.55, 0.42, 0.64),
  vulnerability: new Color3(1, 0.12, 0.32)
};

const THEMES: Record<ArenaTheme, ThemePalette> = {
  crypt: { ground: new Color3(0.065, 0.06, 0.078), accent: new Color3(0.36, 0.16, 0.48), fog: new Color3(0.035, 0.025, 0.052), light: new Color3(0.65, 0.56, 0.8) },
  ash: { ground: new Color3(0.09, 0.045, 0.035), accent: new Color3(0.88, 0.22, 0.045), fog: new Color3(0.065, 0.018, 0.018), light: new Color3(1, 0.48, 0.24) },
  frost: { ground: new Color3(0.035, 0.065, 0.085), accent: new Color3(0.18, 0.7, 1), fog: new Color3(0.02, 0.052, 0.072), light: new Color3(0.48, 0.82, 1) },
  ink: { ground: new Color3(0.045, 0.025, 0.07), accent: new Color3(0.64, 0.18, 1), fog: new Color3(0.035, 0.012, 0.055), light: new Color3(0.74, 0.36, 1) },
  throne: { ground: new Color3(0.075, 0.052, 0.045), accent: new Color3(0.82, 0.58, 0.18), fog: new Color3(0.042, 0.025, 0.028), light: new Color3(1, 0.72, 0.42) }
};

export class BabylonGameView {
  private readonly engine: Engine;
  private readonly scene: Scene;
  private readonly camera: ArcRotateCamera;
  private readonly keyLight: DirectionalLight;
  private readonly ground: Mesh;
  private readonly groundMaterial: StandardMaterial;
  private readonly borderMaterial: StandardMaterial;
  private readonly vfx: VfxSystem;
  private readonly assets = new AssetRegistry();
  private readonly actors = new Map<string, ActorView>();
  private readonly environmentNodes: TransformNode[] = [];
  private settings: GameSettings = {
    version: 1,
    masterVolume: 0.72,
    effectsVolume: 0.78,
    reducedMotion: false,
    reducedVfx: false,
    highContrast: false,
    showDamageNumbers: true,
    gameSpeed: 1,
    language: "fr"
  };
  private elapsed = 0;
  private shakeTime = 0;
  private shakeStrength = 0;
  private currentTheme: ArenaTheme = "crypt";
  private chapter = 1;
  private readonly resizeHandler = () => this.engine.resize();

  public constructor(canvas: HTMLCanvasElement) {
    this.engine = new Engine(canvas, true, { stencil: true, preserveDrawingBuffer: false }, true);
    this.scene = new Scene(this.engine);
    this.scene.clearColor = new Color4(0.012, 0.008, 0.018, 1);
    this.scene.fogMode = Scene.FOGMODE_EXP2;
    this.scene.fogDensity = 0.022;
    this.scene.fogColor = THEMES.crypt.fog;

    this.camera = new ArcRotateCamera("arena-camera", -Math.PI / 2, 1.08, 17.8, new Vector3(0, 0.25, 0), this.scene);
    this.camera.fov = 0.72;
    this.camera.lowerRadiusLimit = 15;
    this.camera.upperRadiusLimit = 23;
    this.camera.inputs.clear();

    const hemi = new HemisphericLight("hemi", new Vector3(0, 1, 0), this.scene);
    hemi.intensity = 0.36;
    hemi.diffuse = new Color3(0.54, 0.5, 0.68);
    this.keyLight = new DirectionalLight("key", new Vector3(-0.45, -1, 0.35), this.scene);
    this.keyLight.position = new Vector3(8, 12, -8);
    this.keyLight.intensity = 2.4;
    this.keyLight.diffuse = THEMES.crypt.light;
    const shadows = new ShadowGenerator(1024, this.keyLight);
    shadows.useBlurExponentialShadowMap = true;
    shadows.blurKernel = 24;

    this.ground = MeshBuilder.CreateCylinder("arena", { height: 0.34, diameter: 15.2, tessellation: 72 }, this.scene);
    this.ground.position.y = -0.24;
    this.ground.receiveShadows = true;
    this.groundMaterial = new StandardMaterial("arena-material", this.scene);
    this.groundMaterial.diffuseColor = THEMES.crypt.ground;
    this.groundMaterial.specularColor = new Color3(0.18, 0.14, 0.22);
    this.ground.material = this.groundMaterial;

    const inner = MeshBuilder.CreateTorus("arena-inner-glyph", { diameter: 9.2, thickness: 0.025, tessellation: 96 }, this.scene);
    inner.rotation.x = Math.PI / 2;
    inner.position.y = 0.005;
    const innerMaterial = new StandardMaterial("inner-glyph-material", this.scene);
    innerMaterial.emissiveColor = THEMES.crypt.accent.scale(0.5);
    innerMaterial.disableLighting = true;
    inner.material = innerMaterial;

    const border = MeshBuilder.CreateTorus("arena-border", { diameter: 14.8, thickness: 0.075, tessellation: 96 }, this.scene);
    border.rotation.x = Math.PI / 2;
    border.position.y = 0.015;
    this.borderMaterial = new StandardMaterial("border-material", this.scene);
    this.borderMaterial.emissiveColor = THEMES.crypt.accent;
    this.borderMaterial.disableLighting = true;
    border.material = this.borderMaterial;

    const glow = new GlowLayer("glow", this.scene);
    glow.intensity = 0.55;
    const pipeline = new DefaultRenderingPipeline("render-pipeline", true, this.scene, [this.camera]);
    pipeline.bloomEnabled = true;
    pipeline.bloomThreshold = 0.72;
    pipeline.bloomWeight = 0.28;
    pipeline.fxaaEnabled = true;
    pipeline.imageProcessingEnabled = true;
    pipeline.imageProcessing.contrast = 1.14;
    pipeline.imageProcessing.exposure = 1.03;

    this.vfx = new VfxSystem(this.scene);
    this.rebuildEnvironment();
    window.addEventListener("resize", this.resizeHandler);
  }

  public async initialize(): Promise<void> {
    await this.assets.initialize();
  }

  public updateSettings(settings: GameSettings): void {
    this.settings = settings;
    this.vfx.setIntensity(settings.reducedVfx ? 0.42 : 1);
    this.scene.fogDensity = settings.highContrast ? 0.013 : 0.022;
  }

  public setArenaTheme(theme: ArenaTheme, chapter: number): void {
    if (theme === this.currentTheme && chapter === this.chapter) return;
    this.currentTheme = theme;
    this.chapter = chapter;
    const palette = THEMES[theme];
    this.groundMaterial.diffuseColor = palette.ground;
    this.borderMaterial.emissiveColor = palette.accent;
    this.scene.fogColor = palette.fog;
    this.keyLight.diffuse = palette.light;
    this.rebuildEnvironment();
  }

  public sync(snapshot: CombatSnapshot): void {
    const ids = new Set(snapshot.actors.map((actor) => actor.id));
    for (const [id, view] of this.actors) {
      if (!ids.has(id)) {
        view.root.dispose(false, true);
        this.actors.delete(id);
      }
    }

    for (const actor of snapshot.actors) {
      let view = this.actors.get(actor.id);
      if (!view) {
        view = this.createFallbackActor(actor);
        this.actors.set(actor.id, view);
        this.tryAttachModel(actor, view);
      }
      view.targetPosition.set(actor.x / 100, view.baseY, actor.z / 100);
      view.root.setEnabled(actor.alive);
      const primary = actor.statuses[0]?.kind;
      const secondary = actor.statuses[1]?.kind;
      view.primaryMaterial.emissiveColor = primary ? STATUS_COLORS[primary].scale(0.34) : Color3.Black();
      view.accentMaterial.emissiveColor = secondary ? STATUS_COLORS[secondary].scale(0.48) : actor.side === "hero" ? new Color3(0.2, 0.58, 1) : new Color3(0.72, 0.08, 0.055);
      view.ringMaterial.emissiveColor = actor.bossId
        ? THEMES[this.currentTheme].accent.scale(1.25)
        : actor.side === "hero"
          ? new Color3(0.22, 0.68, 1)
          : actor.side === "ally"
            ? new Color3(0.42, 0.9, 0.7)
            : new Color3(1, 0.11, 0.055);
      const healthScale = Math.max(0.2, actor.health / actor.maxHealth);
      view.ring.scaling.set(healthScale, healthScale, healthScale);
    }
  }

  public handleEvents(events: EventEnvelope[]): void {
    for (const event of events) {
      const source = event.sourceId ? this.actors.get(event.sourceId) : undefined;
      const target = event.targetId ? this.actors.get(event.targetId) : undefined;
      const sourcePosition = source?.root.position.clone() ?? Vector3.Zero();
      const targetPosition = target?.root.position.clone() ?? sourcePosition.clone();
      sourcePosition.y += 0.7;
      targetPosition.y += 0.62;

      if (event.type === "TelegraphStarted") {
        const radius = Number(event.payload.radius ?? 180) / 100;
        this.vfx.telegraph(target?.root.position.clone() ?? Vector3.Zero(), new Color3(1, 0.08, 0.025), radius, Math.max(0.25, Number(event.payload.durationTicks ?? 8) / 20));
      }
      if (event.type === "AttackStarted") {
        if (Boolean(event.payload.projectile)) this.vfx.beam(sourcePosition, targetPosition, new Color3(0.72, 0.26, 1), 0.045, 0.11);
        else this.vfx.slash(targetPosition, Boolean(event.payload.critical) ? new Color3(1, 0.82, 0.24) : new Color3(0.95, 0.22, 0.12), Boolean(event.payload.heavy) ? 1.55 : 1.05);
      }
      if (event.type === "ProjectileCreated") {
        const color = event.tags.includes("shard") ? STATUS_COLORS.freeze : event.tags.includes("bounce") ? new Color3(1, 0.74, 0.2) : new Color3(0.68, 0.24, 1);
        this.vfx.beam(sourcePosition, targetPosition, color, event.tags.includes("shard") ? 0.04 : 0.055, 0.13);
      }
      if (event.type === "DamageDealt") {
        const critical = Boolean(event.payload.critical);
        const color = event.tags.includes("poison") ? STATUS_COLORS.poison : event.tags.includes("burn") ? STATUS_COLORS.burn : critical ? new Color3(1, 0.9, 0.42) : new Color3(1, 0.18, 0.09);
        this.vfx.burst(targetPosition, color, critical ? 16 : 7, critical ? 3.1 : 1.8, critical ? 0.58 : 0.38);
        this.kickCamera(critical ? 0.22 : event.tags.includes("explosion") ? 0.18 : 0.07, critical ? 0.18 : 0.1);
      }
      if (event.type === "StatusApplied") {
        const status = String(event.payload.status) as StatusKind;
        this.vfx.ring(target?.root.position.clone() ?? Vector3.Zero(), STATUS_COLORS[status] ?? Color3.White(), 0.85, 0.48, 0.038);
        this.vfx.burst(targetPosition, STATUS_COLORS[status] ?? Color3.White(), 9, 1.35, 0.55);
      }
      if (event.type === "ExplosionCreated") {
        const radius = Number(event.payload.radius ?? 300) / 100;
        const color = event.tags.includes("corruption") ? STATUS_COLORS.vulnerability : STATUS_COLORS.burn;
        this.vfx.ring(target?.root.position.clone() ?? Vector3.Zero(), color, radius, 0.72, 0.075);
        this.vfx.burst(targetPosition, color, 28, 4.4, 0.75);
        this.kickCamera(0.32, 0.32);
      }
      if (event.type === "HealingReceived") {
        this.vfx.ring(target?.root.position.clone() ?? Vector3.Zero(), new Color3(0.2, 1, 0.46), 1.15, 0.62, 0.05);
        this.vfx.burst(targetPosition, new Color3(0.3, 1, 0.55), 12, 1.2, 0.8);
      }
      if (event.type === "ShieldGained" || event.type === "ShieldBroken") {
        this.vfx.ring(target?.root.position.clone() ?? Vector3.Zero(), new Color3(0.25, 0.68, 1), event.type === "ShieldBroken" ? 1.65 : 1.05, 0.55, 0.045);
      }
      if (event.type === "RewriteUsed") {
        this.vfx.ring(Vector3.Zero(), new Color3(0.72, 0.18, 1), 5.8, 0.95, 0.11);
        this.vfx.burst(new Vector3(0, 0.8, 0), new Color3(0.75, 0.24, 1), 32, 4.8, 1.15);
        this.kickCamera(0.24, 0.24);
      }
      if (event.type === "BossMechanic") {
        const color = String(event.payload.kind) === "corrupt" ? new Color3(1, 0.05, 0.28) : new Color3(0.72, 0.18, 1);
        this.vfx.ring(target?.root.position.clone() ?? Vector3.Zero(), color, 4.5, 1.2, 0.09);
        this.kickCamera(0.28, 0.3);
      }
      if (event.type === "EnemyKilled" || event.type === "AllyKilled") {
        this.vfx.burst(targetPosition, event.type === "EnemyKilled" ? new Color3(0.58, 0.08, 0.11) : new Color3(0.2, 0.58, 1), 24, 3.5, 0.85);
      }
      if (event.type === "ActorSummoned") {
        this.vfx.ring(target?.root.position.clone() ?? Vector3.Zero(), new Color3(0.24, 0.9, 0.72), 1.3, 0.75, 0.06);
      }
    }
  }

  public clearCombat(): void {
    for (const view of this.actors.values()) view.root.dispose(false, true);
    this.actors.clear();
    this.vfx.clear();
  }

  public render(deltaSeconds: number): void {
    this.elapsed += deltaSeconds;
    const motionScale = this.settings.reducedMotion ? 0.15 : 1;
    for (const view of this.actors.values()) {
      view.root.position = Vector3.Lerp(view.root.position, view.targetPosition, Math.min(1, deltaSeconds * 12));
      const bob = Math.sin(this.elapsed * 2.1 + view.phaseOffset) * 0.025 * motionScale;
      view.root.position.y = view.baseY + bob;
      view.ring.rotation.z += deltaSeconds * 0.28 * motionScale;
    }

    if (this.shakeTime > 0 && !this.settings.reducedMotion) {
      this.shakeTime -= deltaSeconds;
      const strength = this.shakeStrength * Math.max(0, this.shakeTime * 5);
      this.camera.target.set(Math.sin(this.elapsed * 79) * strength, 0.25, Math.cos(this.elapsed * 67) * strength);
    } else {
      this.camera.target = Vector3.Lerp(this.camera.target, new Vector3(0, 0.25, 0), Math.min(1, deltaSeconds * 9));
    }
    this.vfx.update(deltaSeconds);
    this.scene.render();
  }

  public dispose(): void {
    window.removeEventListener("resize", this.resizeHandler);
    this.clearCombat();
    for (const node of this.environmentNodes) node.dispose(false, true);
    this.environmentNodes.length = 0;
    this.vfx.dispose();
    this.scene.dispose();
    this.engine.dispose();
  }

  private createFallbackActor(actor: ActorSnapshot): ActorView {
    const root = new TransformNode(`${actor.id}-root`, this.scene);
    const parts: Mesh[] = [];
    const primaryMaterial = new StandardMaterial(`${actor.id}-primary`, this.scene);
    const accentMaterial = new StandardMaterial(`${actor.id}-accent`, this.scene);
    const palette = actorPalette(actor);
    primaryMaterial.diffuseColor = palette.primary;
    primaryMaterial.specularColor = new Color3(0.28, 0.24, 0.32);
    accentMaterial.diffuseColor = palette.accent.scale(0.4);
    accentMaterial.emissiveColor = palette.accent.scale(0.45);

    const add = (mesh: Mesh, material: StandardMaterial, y = 0): Mesh => {
      mesh.parent = root;
      mesh.position.y = y;
      mesh.material = material;
      parts.push(mesh);
      return mesh;
    };

    let scale = actor.bossId ? 1.65 : actor.elite ? 1.25 : 1;
    if (actor.side === "hero") {
      add(MeshBuilder.CreateCylinder(`${actor.id}-cloak`, { height: 1.4, diameterTop: 0.42, diameterBottom: 0.92, tessellation: 12 }, this.scene), primaryMaterial, 0.72);
      add(MeshBuilder.CreateSphere(`${actor.id}-head`, { diameter: 0.42, segments: 12 }, this.scene), accentMaterial, 1.52);
      const weapon = add(MeshBuilder.CreateBox(`${actor.id}-weapon`, { width: 0.08, height: 1.2, depth: 0.12 }, this.scene), accentMaterial, 0.94);
      weapon.position.x = 0.5;
      weapon.rotation.z = -0.28;
    } else if (actor.behavior === "crawler") {
      const body = add(MeshBuilder.CreateSphere(`${actor.id}-crawler`, { diameter: 0.9, segments: 10 }, this.scene), primaryMaterial, 0.38);
      body.scaling.set(1.3, 0.55, 0.8);
      for (let index = 0; index < 4; index += 1) {
        const leg = add(MeshBuilder.CreateBox(`${actor.id}-leg-${index}`, { width: 0.7, height: 0.06, depth: 0.08 }, this.scene), accentMaterial, 0.28);
        leg.rotation.y = (Math.PI * index) / 4;
      }
    } else if (actor.behavior === "brute") {
      add(MeshBuilder.CreateBox(`${actor.id}-brute`, { width: 1.1, height: 1.35, depth: 0.8 }, this.scene), primaryMaterial, 0.72);
      const hammer = add(MeshBuilder.CreateBox(`${actor.id}-hammer`, { width: 0.34, height: 1.45, depth: 0.34 }, this.scene), accentMaterial, 0.85);
      hammer.position.x = 0.75;
      scale *= 1.1;
    } else if (actor.behavior === "caster" || actor.behavior === "summoner") {
      add(MeshBuilder.CreateCylinder(`${actor.id}-robe`, { height: 1.15, diameterTop: 0.3, diameterBottom: 0.76, tessellation: 10 }, this.scene), primaryMaterial, 0.62);
      const orb = add(MeshBuilder.CreateSphere(`${actor.id}-orb`, { diameter: 0.34, segments: 12 }, this.scene), accentMaterial, 1.4);
      orb.position.x = 0.48;
    } else if (actor.behavior === "ranged") {
      add(MeshBuilder.CreateCylinder(`${actor.id}-body`, { height: 1.2, diameter: 0.5, tessellation: 10 }, this.scene), primaryMaterial, 0.65);
      const bow = add(MeshBuilder.CreateTorus(`${actor.id}-bow`, { diameter: 0.95, thickness: 0.055, tessellation: 24 }, this.scene), accentMaterial, 0.78);
      bow.position.x = 0.43;
      bow.rotation.z = Math.PI / 2;
    } else {
      add(MeshBuilder.CreateCylinder(`${actor.id}-body`, { height: 1.25, diameterTop: 0.5, diameterBottom: 0.68, tessellation: 10 }, this.scene), primaryMaterial, 0.66);
      const blade = add(MeshBuilder.CreateBox(`${actor.id}-blade`, { width: 0.07, height: 0.92, depth: 0.11 }, this.scene), accentMaterial, 0.78);
      blade.position.x = 0.44;
      blade.rotation.z = -0.3;
    }

    if (actor.elite || actor.bossId) {
      const crown = add(MeshBuilder.CreateTorus(`${actor.id}-crown`, { diameter: actor.bossId ? 1.15 : 0.82, thickness: 0.065, tessellation: 32 }, this.scene), accentMaterial, actor.bossId ? 1.85 : 1.5);
      crown.rotation.x = Math.PI / 2;
      for (let index = 0; index < (actor.bossId ? 6 : 3); index += 1) {
        const spike = add(MeshBuilder.CreateCylinder(`${actor.id}-spike-${index}`, { height: 0.48, diameterTop: 0, diameterBottom: 0.13, tessellation: 6 }, this.scene), accentMaterial, actor.bossId ? 1.95 : 1.6);
        const angle = (Math.PI * 2 * index) / (actor.bossId ? 6 : 3);
        spike.position.x = Math.cos(angle) * (actor.bossId ? 0.54 : 0.37);
        spike.position.z = Math.sin(angle) * (actor.bossId ? 0.54 : 0.37);
      }
    }

    root.scaling.setAll(scale);
    const ring = MeshBuilder.CreateTorus(`${actor.id}-ring`, { diameter: actor.bossId ? 1.55 : actor.elite ? 1.25 : 1, thickness: actor.bossId ? 0.065 : 0.04, tessellation: 48 }, this.scene);
    ring.parent = root;
    ring.rotation.x = Math.PI / 2;
    ring.position.y = 0.025;
    const ringMaterial = new StandardMaterial(`${actor.id}-ring-material`, this.scene);
    ringMaterial.emissiveColor = palette.accent;
    ringMaterial.disableLighting = true;
    ring.material = ringMaterial;

    const baseY = actor.side === "ally" ? 0.28 : 0;
    root.position.set(actor.x / 100, baseY, actor.z / 100);
    return {
      root,
      parts,
      primaryMaterial,
      accentMaterial,
      ring,
      ringMaterial,
      targetPosition: root.position.clone(),
      baseY,
      phaseOffset: hashToPhase(actor.id),
      modelRequested: false
    };
  }

  private tryAttachModel(actor: ActorSnapshot, view: ActorView): void {
    if (view.modelRequested || !this.assets.hasModel(actor.definitionId)) return;
    view.modelRequested = true;
    void this.assets.instantiate(actor.definitionId, this.scene).then((model) => {
      if (!model || view.root.isDisposed()) return;
      for (const part of view.parts) part.setEnabled(false);
      model.parent = view.root;
    });
  }

  private rebuildEnvironment(): void {
    for (const node of this.environmentNodes) node.dispose(false, true);
    this.environmentNodes.length = 0;
    const palette = THEMES[this.currentTheme];
    for (let index = 0; index < 12; index += 1) {
      const angle = (Math.PI * 2 * index) / 12;
      const radius = 8.2 + (index % 2) * 0.6;
      const root = new TransformNode(`environment-${this.currentTheme}-${index}`, this.scene);
      root.position.set(Math.cos(angle) * radius, 0, Math.sin(angle) * radius);
      const pillar = MeshBuilder.CreateCylinder(`pillar-${index}`, { height: 2.4 + (index % 3) * 0.45, diameter: 0.38 + (index % 2) * 0.14, tessellation: 8 }, this.scene);
      pillar.parent = root;
      pillar.position.y = 1.05;
      const material = new StandardMaterial(`pillar-material-${index}`, this.scene);
      material.diffuseColor = palette.ground.scale(1.45);
      material.emissiveColor = index % 3 === 0 ? palette.accent.scale(0.06) : Color3.Black();
      pillar.material = material;
      if (index % 3 === 0) {
        const flame = MeshBuilder.CreateSphere(`flame-${index}`, { diameter: 0.16, segments: 8 }, this.scene);
        flame.parent = root;
        flame.position.y = 2.3;
        const flameMaterial = new StandardMaterial(`flame-material-${index}`, this.scene);
        flameMaterial.emissiveColor = palette.accent.scale(1.4);
        flameMaterial.disableLighting = true;
        flame.material = flameMaterial;
        const light = new PointLight(`torch-light-${index}`, new Vector3(0, 2.3, 0), this.scene);
        light.parent = root;
        light.diffuse = palette.light;
        light.intensity = 0.55;
        light.range = 5;
      }
      this.environmentNodes.push(root);
    }
  }

  private kickCamera(strength: number, duration: number): void {
    if (this.settings.reducedMotion) return;
    this.shakeStrength = Math.max(this.shakeStrength, strength);
    this.shakeTime = Math.max(this.shakeTime, duration);
  }
}

function actorPalette(actor: ActorSnapshot): { primary: Color3; accent: Color3 } {
  if (actor.side === "hero") return { primary: new Color3(0.09, 0.075, 0.13), accent: new Color3(0.24, 0.65, 1) };
  if (actor.side === "ally") return { primary: new Color3(0.065, 0.15, 0.13), accent: new Color3(0.3, 0.92, 0.7) };
  if (actor.bossId === "author") return { primary: new Color3(0.12, 0.015, 0.025), accent: new Color3(1, 0.04, 0.25) };
  if (actor.bossId) return { primary: new Color3(0.12, 0.05, 0.16), accent: new Color3(0.72, 0.18, 1) };
  if (actor.elite) return { primary: new Color3(0.17, 0.055, 0.08), accent: new Color3(1, 0.45, 0.08) };
  if (actor.behavior === "caster" || actor.behavior === "summoner") return { primary: new Color3(0.105, 0.04, 0.15), accent: new Color3(0.65, 0.18, 0.92) };
  if (actor.behavior === "ranged") return { primary: new Color3(0.13, 0.08, 0.065), accent: new Color3(0.92, 0.34, 0.1) };
  if (actor.behavior === "crawler") return { primary: new Color3(0.08, 0.12, 0.08), accent: new Color3(0.36, 0.92, 0.22) };
  return { primary: new Color3(0.18, 0.055, 0.045), accent: new Color3(0.95, 0.16, 0.065) };
}

function hashToPhase(value: string): number {
  let hash = 0;
  for (let index = 0; index < value.length; index += 1) hash = (hash * 31 + value.charCodeAt(index)) >>> 0;
  return (hash % 628) / 100;
}
