/**
 * Navigation manette sans dépendance : le héros reste automatique, la manette
 * ne fait que piloter les mêmes contrôles accessibles que le clavier/souris.
 */
export class GamepadController {
  private frame = 0;
  private previousButtons: boolean[] = [];
  private previousAxes = [0, 0];
  private disposed = false;

  public start(): void {
    if (this.disposed || this.frame) return;
    this.frame = requestAnimationFrame(this.update);
  }

  public dispose(): void {
    this.disposed = true;
    cancelAnimationFrame(this.frame);
    this.frame = 0;
  }

  private readonly update = (): void => {
    if (this.disposed) return;
    const gamepad = navigator.getGamepads?.().find((entry): entry is Gamepad => Boolean(entry));
    if (gamepad) this.read(gamepad);
    this.frame = requestAnimationFrame(this.update);
  };

  private read(gamepad: Gamepad): void {
    const pressed = gamepad.buttons.map((button) => button.pressed);
    const edge = (index: number): boolean => Boolean(pressed[index] && !this.previousButtons[index]);
    const horizontal = deadZone(gamepad.axes[0] ?? 0);
    const vertical = deadZone(gamepad.axes[1] ?? 0);
    const horizontalEdge = Math.sign(horizontal) !== 0 && Math.sign(horizontal) !== Math.sign(this.previousAxes[0] ?? 0);
    const verticalEdge = Math.sign(vertical) !== 0 && Math.sign(vertical) !== Math.sign(this.previousAxes[1] ?? 0);

    if (edge(0)) this.activateFocused(); // A / Croix
    if (edge(1)) this.dispatchKey("Escape"); // B / Rond
    if (edge(2)) this.dispatchKey("c"); // X / Carré
    if (edge(3)) this.dispatchKey("r"); // Y / Triangle
    if (edge(9)) this.dispatchKey(" ", "Space"); // Start

    if (edge(12) || (verticalEdge && vertical < 0)) this.moveFocus(0, -1);
    if (edge(13) || (verticalEdge && vertical > 0)) this.moveFocus(0, 1);
    if (edge(14) || (horizontalEdge && horizontal < 0)) this.moveFocus(-1, 0);
    if (edge(15) || (horizontalEdge && horizontal > 0)) this.moveFocus(1, 0);

    this.previousButtons = pressed;
    this.previousAxes = [horizontal, vertical];
  }

  private activateFocused(): void {
    const active = document.activeElement;
    if (active instanceof HTMLElement && active.matches("button:not(:disabled), summary, [role='button']")) {
      active.click();
      return;
    }
    this.focusables()[0]?.focus();
  }

  private moveFocus(dx: number, dy: number): void {
    const elements = this.focusables();
    if (!elements.length) return;
    const active = document.activeElement instanceof HTMLElement ? document.activeElement : undefined;
    if (!active || !elements.includes(active)) {
      elements[0]?.focus();
      return;
    }
    const origin = center(active.getBoundingClientRect());
    let best: { element: HTMLElement; score: number } | undefined;
    for (const element of elements) {
      if (element === active) continue;
      const target = center(element.getBoundingClientRect());
      const x = target.x - origin.x;
      const y = target.y - origin.y;
      if ((dx < 0 && x >= -2) || (dx > 0 && x <= 2) || (dy < 0 && y >= -2) || (dy > 0 && y <= 2)) continue;
      const primary = dx === 0 ? Math.abs(y) : Math.abs(x);
      const secondary = dx === 0 ? Math.abs(x) : Math.abs(y);
      const score = primary + secondary * 2.2;
      if (!best || score < best.score) best = { element, score };
    }
    (best?.element ?? elements[(elements.indexOf(active) + 1) % elements.length])?.focus();
  }

  private focusables(): HTMLElement[] {
    return [...document.querySelectorAll<HTMLElement>("button:not(:disabled), input:not(:disabled), select:not(:disabled), summary, [tabindex]:not([tabindex='-1'])")]
      .filter((element) => element.offsetParent !== null && !element.hasAttribute("aria-hidden"));
  }

  private dispatchKey(key: string, code = key): void {
    window.dispatchEvent(new KeyboardEvent("keydown", { key, code, bubbles: true }));
  }
}

function deadZone(value: number): number {
  return Math.abs(value) < 0.55 ? 0 : value;
}

function center(rect: DOMRect): { x: number; y: number } {
  return { x: rect.left + rect.width / 2, y: rect.top + rect.height / 2 };
}
