import { ENEMY_BY_ID, RULE_BY_ID, getEnemy, getRule } from "../content/gameContent";
import { clamp, distanceSquared, moveAway, moveToward, percentage, withinRadius } from "./math";
import { SeededRng, hashString } from "./rng";
import type {
  ActiveRewrite,
  ActorSnapshot,
  CombatActor,
  CombatConfig,
  CombatEventType,
  CombatSnapshot,
  CombatState,
  EntityId,
  EventEnvelope,
  RewriteKind,
  RuleDefinition,
  RuleEffect,
  RuleId,
  StatusInstance,
  StatusKind,
  TargetingMode,
} from "./types";

const MAX_EVENTS_PER_CHAIN = 320;
const MAX_CHAIN_DEPTH = 26;
const MAX_RULE_TRIGGERS_PER_CHAIN = 84;
const EVENT_HISTORY_LIMIT = 260;
const ARENA_RADIUS = 650;

const BASE_REWRITE_COSTS: Record<RewriteKind, number> = {
  swap: 35,
  disable: 25,
  trigger: 40,
  copy: 60,
  retarget: 20,
  "suppress-sacrifice": 70,
};

interface CombatMetrics {
  enemiesKilled: number;
  elitesKilled: number;
  rulesTriggered: number;
  rewritesUsed: number;
  damageDealt: number;
  damageTaken: number;
  healingReceived: number;
  longestChain: number;
}

interface RewriteRequest {
  firstIndex?: number;
  secondIndex?: number;
  ruleIndex?: number;
  targetingMode?: TargetingMode;
}

export class CombatSimulation {
  private readonly config: CombatConfig;
  private readonly rng: SeededRng;
  private readonly ruleLevels = new Map<RuleId, number>();
  private readonly queue: EventEnvelope[] = [];
  private readonly history: EventEnvelope[] = [];
  private readonly deathQueued = new Set<EntityId>();
  private readonly permanentlyConsumedRules = new Set<RuleId>();
  private readonly metrics: CombatMetrics = {
    enemiesKilled: 0,
    elitesKilled: 0,
    rulesTriggered: 0,
    rewritesUsed: 0,
    damageDealt: 0,
    damageTaken: 0,
    healingReceived: 0,
    longestChain: 0,
  };
  private state: CombatState;

  public constructor(config: CombatConfig) {
    this.config = structuredClone(config);
    this.rng = new SeededRng(config.seed ^ hashString(config.encounter.id));
    for (const instance of config.codex) this.ruleLevels.set(instance.ruleId, instance.level);
    this.state = this.createInitialState();
  }

  public start(): void {
    if (this.state.status !== "ready" && this.state.status !== "paused") return;
    this.state.status = "running";
    if (this.state.tick === 0) {
      this.enqueue("CombatStarted", {
        encounter: this.config.encounter.name,
        chapter: this.config.encounter.chapter,
      });
      this.resolveQueue();
    }
  }

  public pause(): void {
    if (this.state.status === "running") this.state.status = "paused";
  }

  public setReadyCodexOrder(ruleIds: RuleId[]): boolean {
    if (this.state.status !== "ready" || ruleIds.length < 1) return false;
    if (new Set(ruleIds).size !== ruleIds.length) return false;
    if (ruleIds.some((ruleId) => !this.ruleLevels.has(ruleId))) return false;
    this.state.codexOrder = [...ruleIds];
    return true;
  }

  public setReadyTargetingMode(mode: TargetingMode): boolean {
    if (this.state.status !== "ready") return false;
    this.state.targetingMode = mode;
    return true;
  }

  public step(): void {
    if (this.state.status !== "running") return;
    this.state.tick += 1;
    this.expireTemporaryState();
    this.tickStatuses();
    this.tickBossMechanics();
    this.updateActors();
    this.resolveQueue();
    this.evaluateCombatEnd();
  }

  public requestRewrite(kind: RewriteKind, request: RewriteRequest = {}): boolean {
    if (this.state.status !== "running" && this.state.status !== "paused") return false;
    const cost = this.getRewriteCost(kind);
    if (this.state.ink < cost) return false;
    if (kind === "swap" && this.state.activeRewrites.some((rewrite) => rewrite.kind === "swap")) return false;
    if (kind === "retarget" && this.state.activeRewrites.some((rewrite) => rewrite.kind === "retarget"))
      return false;

    const now = this.state.tick;
    let rewrite: ActiveRewrite | undefined;
    if (kind === "swap") {
      const first = request.firstIndex;
      const second = request.secondIndex;
      if (first === undefined || second === undefined || first === second) return false;
      if (!this.state.codexOrder[first] || !this.state.codexOrder[second]) return false;
      const previousOrder = [...this.state.codexOrder];
      [this.state.codexOrder[first], this.state.codexOrder[second]] = [
        this.state.codexOrder[second] as RuleId,
        this.state.codexOrder[first] as RuleId,
      ];
      rewrite = { kind, firstIndex: first, secondIndex: second, previousOrder, expiresAtTick: now + 180 };
    } else if (kind === "disable") {
      const index = request.ruleIndex;
      if (index === undefined || !this.state.codexOrder[index]) return false;
      this.state.disabledRuleUntil[index] = Math.max(this.state.disabledRuleUntil[index] ?? 0, now + 150);
      rewrite = { kind, ruleIndex: index, expiresAtTick: now + 150 };
    } else if (kind === "trigger") {
      const index = request.ruleIndex;
      const ruleId = index === undefined ? undefined : this.state.codexOrder[index];
      if (index === undefined || !ruleId || this.isRuleDisabled(index)) return false;
      rewrite = { kind, ruleIndex: index, expiresAtTick: now + 1 };
      this.forceTriggerRule(index, ruleId);
    } else if (kind === "copy") {
      const index = request.ruleIndex;
      const ruleId = index === undefined ? undefined : this.state.codexOrder[index];
      if (index === undefined || !ruleId || this.state.copiedRule) return false;
      this.state.copiedRule = { ruleId, sourceIndex: index, expiresAtTick: now + 160 };
      rewrite = { kind, ruleIndex: index, expiresAtTick: now + 160 };
    } else if (kind === "retarget") {
      const previousTargeting = this.state.targetingMode;
      const next = request.targetingMode ?? nextTargetingMode(previousTargeting);
      this.state.targetingMode = next;
      rewrite = { kind, previousTargeting, expiresAtTick: now + 200 };
    } else if (kind === "suppress-sacrifice") {
      this.state.suppressSacrificeUntilTick = Math.max(this.state.suppressSacrificeUntilTick, now + 160);
      rewrite = { kind, expiresAtTick: now + 160 };
    }

    if (!rewrite) return false;
    this.state.ink -= cost;
    this.state.activeRewrites.push(rewrite);
    this.metrics.rewritesUsed += 1;
    this.enqueue(
      "RewriteUsed",
      { kind, cost, message: rewriteMessage(kind, request), expiresAtTick: rewrite.expiresAtTick },
      "hero",
      undefined,
      undefined,
      undefined,
      ["rewrite"],
    );
    this.resolveQueue();
    return true;
  }

  public getSnapshot(): CombatSnapshot {
    const actors: ActorSnapshot[] = [...this.state.actors.values()]
      .sort((a, b) => a.id.localeCompare(b.id))
      .map((actor) => ({
        id: actor.id,
        definitionId: actor.definitionId,
        displayName: actor.displayName,
        side: actor.side,
        behavior: actor.behavior,
        x: actor.position.x,
        z: actor.position.z,
        health: actor.health,
        maxHealth: actor.maxHealth,
        shield: actor.shield,
        alive: actor.alive,
        elite: actor.elite,
        bossId: actor.bossId,
        phase: actor.phase,
        statuses: Object.values(actor.statuses)
          .filter((value): value is StatusInstance => Boolean(value))
          .map((status) => ({
            kind: status.kind,
            remainingTicks: status.remainingTicks,
            stacks: status.stacks,
          })),
      }));

    const copied = this.state.copiedRule;
    return {
      tick: this.state.tick,
      tickRate: this.config.tickRate,
      status: this.state.status,
      encounter: this.config.encounter,
      actors,
      codex: this.state.codexOrder.map((ruleId, index) => ({
        definition: getRule(ruleId),
        level: this.ruleLevels.get(ruleId) ?? 1,
        disabled: this.isRuleDisabled(index) || this.permanentlyConsumedRules.has(ruleId),
        copied: copied?.sourceIndex === index,
      })),
      ink: this.state.ink,
      maxInk: this.state.maxInk,
      goldEarned: this.state.goldEarned,
      rewriteCosts: {
        swap: this.getRewriteCost("swap"),
        disable: this.getRewriteCost("disable"),
        trigger: this.getRewriteCost("trigger"),
        copy: this.getRewriteCost("copy"),
        retarget: this.getRewriteCost("retarget"),
        "suppress-sacrifice": this.getRewriteCost("suppress-sacrifice"),
      },
      activeRewrites: this.state.activeRewrites.map((entry) => ({ ...entry })),
      targetingMode: this.state.targetingMode,
      direction: this.state.direction,
      corruptedRuleIndex:
        this.state.corruptedUntilTick > this.state.tick ? this.state.corruptedRuleIndex : undefined,
      recentEvents: this.history.slice(-24),
      stateHash: this.getStateHash(),
    };
  }

  public getEventsSince(sequence: number): EventEnvelope[] {
    return this.history.filter((event) => event.sequence > sequence);
  }

  public getStateHash(): string {
    const stable = JSON.stringify({
      tick: this.state.tick,
      status: this.state.status,
      ink: this.state.ink,
      gold: this.state.goldEarned,
      direction: this.state.direction,
      codex: this.state.codexOrder,
      actors: [...this.state.actors.values()]
        .sort((a, b) => a.id.localeCompare(b.id))
        .map((actor) => ({
          id: actor.id,
          x: actor.position.x,
          z: actor.position.z,
          health: actor.health,
          shield: actor.shield,
          alive: actor.alive,
          statuses: Object.values(actor.statuses)
            .filter((value): value is StatusInstance => Boolean(value))
            .map((status) => [status.kind, status.remainingTicks, status.potency, status.stacks])
            .sort((a, b) => String(a[0]).localeCompare(String(b[0]))),
        })),
    });
    let hash = 2166136261;
    for (let index = 0; index < stable.length; index += 1) {
      hash ^= stable.charCodeAt(index);
      hash = Math.imul(hash, 16777619);
    }
    return (hash >>> 0).toString(16).padStart(8, "0");
  }

  public getResult(): {
    heroHealth: number;
    heroShield: number;
    ink: number;
    goldEarned: number;
    enemiesKilled: number;
    elitesKilled: number;
    rulesTriggered: number;
    rewritesUsed: number;
    damageDealt: number;
    damageTaken: number;
    healingReceived: number;
    longestChain: number;
  } {
    const hero = this.state.actors.get("hero");
    return {
      heroHealth: hero?.health ?? 0,
      heroShield: hero?.shield ?? 0,
      ink: this.state.ink,
      goldEarned: this.state.goldEarned,
      ...this.metrics,
    };
  }

  private createInitialState(): CombatState {
    const actors = new Map<EntityId, CombatActor>();
    const heroClass = this.config.heroClass;
    const maxHealth = heroClass.maxHealth + this.config.heroMaxHealthBonus;
    const noDodge = this.config.activeRuleIds.includes("no-dodge-double");
    actors.set("hero", {
      id: "hero",
      definitionId: heroClass.id,
      displayName: heroClass.name,
      side: "hero",
      behavior: "hero",
      position: { x: 0, z: 0 },
      health: clamp(this.config.heroHealth, 1, maxHealth),
      maxHealth,
      shield: Math.max(0, this.config.heroShield),
      speedPerTick: heroClass.speedPerTick,
      attackDamage: Math.round((heroClass.attackDamage * (100 + this.config.heroDamageBonusPct)) / 100),
      attackRange: heroClass.attackRange,
      attackCooldownTicks: heroClass.attackCooldownTicks,
      cooldownRemaining: 4,
      attackCount: 0,
      dodgeChancePct: noDodge ? 0 : heroClass.dodgeChancePct,
      critChancePct: heroClass.critChancePct,
      alive: true,
      elite: false,
      threat: 10,
      statuses: {},
      resistances: {},
      phase: 1,
    });

    let serial = 1;
    const totalEnemies = this.config.encounter.enemies.reduce((sum, spec) => sum + spec.count, 0);
    let placementIndex = 0;
    for (const spec of this.config.encounter.enemies) {
      const definition = getEnemy(spec.definitionId);
      for (let count = 0; count < spec.count; count += 1) {
        const id = `${spec.definitionId}-${serial.toString().padStart(2, "0")}`;
        serial += 1;
        const angle =
          (Math.PI * 2 * placementIndex) / Math.max(1, totalEnemies) + this.rng.nextFloat() * 0.28;
        const radius = definition.bossId ? 450 : 390 + this.rng.int(-55, 70);
        placementIndex += 1;
        const level = Math.max(1, spec.level);
        const healthScale = 1 + (level - 1) * 0.23 + this.config.difficulty * 0.15;
        const damageScale = 1 + (level - 1) * 0.16 + this.config.difficulty * 0.12;
        actors.set(id, {
          id,
          definitionId: definition.id,
          displayName: definition.name,
          side: "enemy",
          behavior: definition.behavior,
          position: { x: Math.round(Math.cos(angle) * radius), z: Math.round(Math.sin(angle) * radius) },
          health: Math.round(definition.maxHealth * healthScale),
          maxHealth: Math.round(definition.maxHealth * healthScale),
          shield: definition.elite ? Math.round(definition.maxHealth * 0.08 * healthScale) : 0,
          speedPerTick: definition.speedPerTick,
          attackDamage: Math.round(definition.attackDamage * damageScale),
          attackRange: definition.attackRange,
          attackCooldownTicks: Math.max(10, definition.attackCooldownTicks - Math.floor(level / 2)),
          cooldownRemaining: this.rng.int(8, 22),
          attackCount: 0,
          dodgeChancePct: definition.behavior === "crawler" ? 10 : 0,
          critChancePct: definition.critChancePct,
          alive: true,
          elite: Boolean(definition.elite),
          bossId: definition.bossId,
          threat: definition.threat,
          statuses: {},
          resistances: { ...(definition.resistances ?? {}) },
          phase: 1,
        });
      }
    }

    if (heroClass.passive === "ash") {
      const hero = actors.get("hero");
      if (hero)
        hero.statuses.burn = {
          kind: "burn",
          remainingTicks: Number.MAX_SAFE_INTEGER,
          potency: 1,
          stacks: 1,
          sourceId: "hero",
        };
    }

    return {
      seed: this.config.seed,
      tick: 0,
      status: "ready",
      actors,
      codexOrder: [...this.config.activeRuleIds],
      ink: clamp(this.config.ink, 0, this.config.maxInk),
      maxInk: this.config.maxInk,
      goldEarned: 0,
      activeRewrites: [],
      disabledRuleUntil: {},
      targetingMode: "nearest",
      suppressSacrificeUntilTick: 0,
      direction: "ltr",
      directionExpiresAtTick: 0,
      corruptedUntilTick: 0,
      ruleTriggerCounts: {},
      globalCounters: {},
      bossThresholdsTriggered: [],
      nextEventId: 1,
      nextSequence: 1,
      nextChainId: 1,
      nextActorSerial: serial,
    };
  }

  private updateActors(): void {
    const actors = [...this.state.actors.values()]
      .filter((actor) => actor.alive)
      .sort((a, b) => a.id.localeCompare(b.id));
    for (const actor of actors) {
      if (actor.expiresAtTick !== undefined && actor.expiresAtTick <= this.state.tick) {
        actor.alive = false;
        continue;
      }
      const haste = actor.statuses.haste?.potency ?? 0;
      actor.cooldownRemaining = Math.max(0, actor.cooldownRemaining - 1 - Math.floor(haste / 25));
      const target = this.selectTarget(actor);
      if (!target) continue;
      const distanceSq = distanceSquared(actor.position, target.position);
      const inRange = distanceSq <= actor.attackRange * actor.attackRange;
      const prefersDistance =
        actor.behavior === "ranged" || actor.behavior === "caster" || actor.behavior === "summoner";
      if (prefersDistance && distanceSq < Math.pow(actor.attackRange * 0.48, 2)) {
        const previous = actor.position;
        actor.position = moveAway(actor.position, target.position, this.effectiveSpeed(actor), ARENA_RADIUS);
        this.enqueue(
          "ActorMoved",
          { from: previous, to: actor.position },
          actor.id,
          target.id,
          undefined,
          undefined,
          ["movement"],
        );
        continue;
      }
      if (!inRange) {
        const previous = actor.position;
        actor.position = moveToward(actor.position, target.position, this.effectiveSpeed(actor));
        this.enqueue(
          "ActorMoved",
          { from: previous, to: actor.position },
          actor.id,
          target.id,
          undefined,
          undefined,
          ["movement"],
        );
        continue;
      }
      if (actor.cooldownRemaining > 0) continue;
      this.beginAttack(actor, target);
    }
  }

  private beginAttack(source: CombatActor, target: CombatActor): void {
    source.attackCount += 1;
    source.cooldownRemaining = source.attackCooldownTicks;
    const projectile =
      source.behavior === "ranged" || source.behavior === "caster" || source.behavior === "summoner";
    const heavy = source.behavior === "brute" && source.attackCount % 3 === 0;
    const ability = source.behavior === "boss" && source.attackCount % 4 === 0;
    if (heavy || ability) {
      this.enqueue(
        "TelegraphStarted",
        { radius: heavy ? 180 : 250, durationTicks: heavy ? 8 : 12, kind: heavy ? "charge" : "boss" },
        source.id,
        target.id,
        undefined,
        undefined,
        ["telegraph"],
      );
    }

    const dodgeChance = target.side === "hero" ? target.dodgeChancePct : target.dodgeChancePct * 0.5;
    if (this.rng.chance(dodgeChance)) {
      this.enqueue(
        "Dodged",
        { amountAvoided: source.attackDamage },
        source.id,
        target.id,
        undefined,
        undefined,
        ["dodge"],
      );
      return;
    }

    const critical = this.rng.chance(source.critChancePct);
    let amount = source.attackDamage;
    if (heavy) amount = Math.round(amount * 1.55);
    if (ability) amount = Math.round(amount * 1.35);
    const weakness = source.statuses.weakness?.potency ?? 0;
    amount = Math.max(1, Math.round((amount * (100 - weakness)) / 100));
    this.enqueue(
      "AttackStarted",
      { baseDamage: amount, amount, critical, projectile, heavy, ability },
      source.id,
      target.id,
      undefined,
      undefined,
      ["direct", projectile ? "projectile" : "melee", critical ? "critical" : "normal"],
    );
  }

  private selectTarget(actor: CombatActor): CombatActor | undefined {
    const enemySide = actor.side === "enemy" ? new Set(["hero", "ally"]) : new Set(["enemy"]);
    const candidates = [...this.state.actors.values()].filter(
      (candidate) => candidate.alive && enemySide.has(candidate.side),
    );
    if (candidates.length === 0) return undefined;
    if (actor.side === "hero") {
      const mode = this.state.targetingMode;
      candidates.sort((a, b) => {
        if (mode === "lowest-health") {
          const delta = a.health / a.maxHealth - b.health / b.maxHealth;
          if (delta !== 0) return delta;
        } else if (mode === "highest-health") {
          const delta = b.health / b.maxHealth - a.health / a.maxHealth;
          if (delta !== 0) return delta;
        } else if (mode === "ranged-first") {
          const scoreA =
            a.behavior === "ranged" || a.behavior === "caster" || a.behavior === "summoner" ? 0 : 1;
          const scoreB =
            b.behavior === "ranged" || b.behavior === "caster" || b.behavior === "summoner" ? 0 : 1;
          if (scoreA !== scoreB) return scoreA - scoreB;
        }
        const delta =
          distanceSquared(actor.position, a.position) - distanceSquared(actor.position, b.position);
        return delta !== 0 ? delta : a.id.localeCompare(b.id);
      });
      return candidates[0];
    }
    candidates.sort((a, b) => {
      const priorityA = a.side === "hero" ? -100 : 0;
      const priorityB = b.side === "hero" ? -100 : 0;
      const delta =
        priorityA +
        distanceSquared(actor.position, a.position) -
        (priorityB + distanceSquared(actor.position, b.position));
      return delta !== 0 ? delta : a.id.localeCompare(b.id);
    });
    return candidates[0];
  }

  private effectiveSpeed(actor: CombatActor): number {
    const freeze = actor.statuses.freeze ? 48 : 100;
    const haste = actor.statuses.haste?.potency ?? 0;
    return Math.max(1, Math.round((actor.speedPerTick * freeze * (100 + haste)) / 10_000));
  }

  private tickStatuses(): void {
    const actors = [...this.state.actors.values()].sort((a, b) => a.id.localeCompare(b.id));
    for (const actor of actors) {
      if (!actor.alive) continue;
      for (const status of Object.values(actor.statuses)) {
        if (!status) continue;
        if (status.remainingTicks !== Number.MAX_SAFE_INTEGER) status.remainingTicks -= 1;
        if (status.kind === "burn" && this.state.tick % 20 === 0) {
          this.enqueue(
            "StatusTick",
            { status: "burn", amount: status.potency * Math.max(1, status.stacks) },
            status.sourceId,
            actor.id,
            undefined,
            undefined,
            ["status", "burn"],
          );
        }
        if (status.kind === "poison" && this.state.tick % 25 === 0) {
          const chance = this.state.globalCounters.poisonCriticalChance ?? 0;
          const critical = chance > 0 && this.rng.chance(chance);
          const amount = status.potency * Math.max(1, status.stacks) * (critical ? 2 : 1);
          this.enqueue(
            "StatusTick",
            { status: "poison", amount, critical },
            status.sourceId,
            actor.id,
            undefined,
            undefined,
            ["status", "poison", critical ? "critical" : "normal"],
          );
        }
        if (status.remainingTicks <= 0) {
          delete actor.statuses[status.kind];
          this.enqueue(
            "StatusExpired",
            { status: status.kind },
            status.sourceId,
            actor.id,
            undefined,
            undefined,
            ["status-expired", status.kind],
          );
        }
      }
    }
  }

  private tickBossMechanics(): void {
    const boss = [...this.state.actors.values()].find((actor) => actor.alive && actor.bossId);
    if (!boss?.bossId) return;
    const healthPct = percentage(boss.health, boss.maxHealth);
    const thresholds = [75, 50, 25];
    thresholds.forEach((threshold, index) => {
      if (healthPct <= threshold && !this.state.bossThresholdsTriggered.includes(threshold)) {
        this.state.bossThresholdsTriggered.push(threshold);
        boss.phase = index + 2;
        boss.attackDamage = Math.round(boss.attackDamage * 1.12);
        boss.attackCooldownTicks = Math.max(12, boss.attackCooldownTicks - 2);
        this.enqueue(
          "BossMechanic",
          { bossId: boss.bossId, kind: "phase", phase: boss.phase, threshold },
          boss.id,
          "hero",
          undefined,
          undefined,
          ["boss", "phase"],
        );
        if (boss.bossId === "bibliophage") this.consumeCodexSlot(index + 1, boss);
        if (boss.bossId === "author") this.corruptRule(boss, 210);
      }
    });

    if (boss.bossId === "inquisitor" && this.state.tick > 0 && this.state.tick % 320 === 0)
      this.inquisitorCensure(boss);
    if (boss.bossId === "inverted-king" && this.state.tick > 0 && this.state.tick % 250 === 0) {
      this.state.direction = "rtl";
      this.state.directionExpiresAtTick = this.state.tick + 170;
      this.enqueue(
        "BossMechanic",
        { bossId: boss.bossId, kind: "reverse", durationTicks: 170 },
        boss.id,
        "hero",
        undefined,
        undefined,
        ["boss", "codex"],
      );
    }
    if (boss.bossId === "faceless-judge" && this.state.tick > 0 && this.state.tick % 210 === 0)
      this.judgeCopiesFirstRule(boss);
    if (boss.bossId === "author" && this.state.tick > 0 && this.state.tick % 185 === 0)
      this.corruptRule(boss, 145);
  }

  private expireTemporaryState(): void {
    if (this.state.direction === "rtl" && this.state.directionExpiresAtTick <= this.state.tick)
      this.state.direction = "ltr";
    if (this.state.corruptedUntilTick <= this.state.tick) this.state.corruptedRuleIndex = undefined;
    if (this.state.copiedRule && this.state.copiedRule.expiresAtTick <= this.state.tick)
      this.state.copiedRule = undefined;

    const expired = this.state.activeRewrites.filter((rewrite) => rewrite.expiresAtTick <= this.state.tick);
    for (const rewrite of expired) {
      if (rewrite.kind === "swap" && rewrite.previousOrder)
        this.state.codexOrder = [...rewrite.previousOrder];
      if (rewrite.kind === "retarget" && rewrite.previousTargeting)
        this.state.targetingMode = rewrite.previousTargeting;
      this.enqueue(
        "RewriteUsed",
        { kind: rewrite.kind, expired: true, message: "La réécriture s’efface." },
        "hero",
        undefined,
        undefined,
        undefined,
        ["rewrite", "expired"],
      );
    }
    this.state.activeRewrites = this.state.activeRewrites.filter(
      (rewrite) => rewrite.expiresAtTick > this.state.tick,
    );
  }

  private enqueue<TPayload extends Record<string, unknown>>(
    type: CombatEventType,
    payload: TPayload,
    sourceId?: EntityId,
    targetId?: EntityId,
    parent?: EventEnvelope,
    causeRuleId?: RuleId,
    tags: string[] = [],
  ): EventEnvelope<TPayload> {
    const event: EventEnvelope<TPayload> = {
      id: this.state.nextEventId++,
      type,
      tick: this.state.tick,
      sequence: this.state.nextSequence++,
      chainId: parent?.chainId ?? this.state.nextChainId++,
      depth: parent ? parent.depth + 1 : 0,
      sourceId,
      targetId,
      causeRuleId,
      payload,
      tags: [...new Set([...(parent?.tags.filter((tag) => tag.startsWith("manual:")) ?? []), ...tags])],
    };
    this.queue.push(event as EventEnvelope);
    return event;
  }

  private resolveQueue(): void {
    const chainCounts = new Map<number, number>();
    const ruleCounts = new Map<number, number>();
    while (this.queue.length > 0) {
      const event = this.queue.shift();
      if (!event) break;
      const chainCount = (chainCounts.get(event.chainId) ?? 0) + 1;
      chainCounts.set(event.chainId, chainCount);
      this.metrics.longestChain = Math.max(this.metrics.longestChain, chainCount);
      if (chainCount > MAX_EVENTS_PER_CHAIN || event.depth > MAX_CHAIN_DEPTH) {
        this.record({
          ...event,
          type: "CombatEnded",
          payload: { result: "chain-budget", interrupted: true },
          tags: [...event.tags, "safety"],
        });
        continue;
      }

      this.prepareEvent(event);
      this.record(event);
      this.runRules(event, ruleCounts);
      this.applyEvent(event);
    }
  }

  private prepareEvent(event: EventEnvelope): void {
    if (event.type === "HealingReceived" && event.targetId) {
      const target = this.state.actors.get(event.targetId);
      const amount = Math.max(0, Number(event.payload.amount ?? 0));
      if (target) event.payload.overheal = Math.max(0, target.health + amount - target.maxHealth);
    }
    if (event.type === "StatusApplied" && event.targetId) {
      const target = this.state.actors.get(event.targetId);
      const activeStatuses = target
        ? Object.values(target.statuses).filter((value): value is StatusInstance => Boolean(value)).length
        : 0;
      if (activeStatuses >= 3 && !event.tags.includes("third-status")) event.tags.push("third-status");
    }
  }

  private runRules(event: EventEnvelope, chainRuleCounts: Map<number, number>): void {
    const entries = this.buildRuleEntries();
    const ordered = this.state.direction === "ltr" ? entries : [...entries].reverse();
    const manualId = event.tags.find((tag) => tag.startsWith("manual:"))?.slice("manual:".length);

    for (const entry of ordered) {
      if (entry.disabled || this.permanentlyConsumedRules.has(entry.rule.id)) continue;
      if (manualId && manualId !== entry.rule.id) continue;
      if (!manualId && entry.rule.trigger !== event.type) continue;
      if (entry.rule.id === event.causeRuleId && event.type === "RuleTriggered") continue;
      if (!this.conditionsPass(entry.rule, event)) continue;

      const count = (chainRuleCounts.get(event.chainId) ?? 0) + 1;
      chainRuleCounts.set(event.chainId, count);
      if (count > MAX_RULE_TRIGGERS_PER_CHAIN) return;
      this.state.ruleTriggerCounts[entry.rule.id] = (this.state.ruleTriggerCounts[entry.rule.id] ?? 0) + 1;
      this.metrics.rulesTriggered += 1;
      this.enqueue(
        "RuleTriggered",
        {
          ruleId: entry.rule.id,
          ruleName: entry.rule.name,
          sourceEventId: event.id,
          copied: entry.copied,
          index: entry.index,
        },
        event.sourceId,
        event.targetId,
        event,
        entry.rule.id,
        ["rule-trigger"],
      );
      const scale = this.ruleScale(entry.rule.id) * (entry.copied ? 0.72 : 1);
      for (const effect of entry.rule.effects)
        this.applyEffect(entry.rule, effect, event, entry.index, scale);
    }
  }

  private buildRuleEntries(): Array<{
    rule: RuleDefinition;
    index: number;
    copied: boolean;
    disabled: boolean;
  }> {
    const result: Array<{ rule: RuleDefinition; index: number; copied: boolean; disabled: boolean }> = [];
    this.state.codexOrder.forEach((ruleId, index) => {
      result.push({ rule: getRule(ruleId), index, copied: false, disabled: this.isRuleDisabled(index) });
      if (
        this.state.copiedRule?.sourceIndex === index &&
        this.state.copiedRule.expiresAtTick > this.state.tick
      ) {
        result.push({ rule: getRule(this.state.copiedRule.ruleId), index, copied: true, disabled: false });
      }
    });
    return result;
  }

  private conditionsPass(rule: RuleDefinition, event: EventEnvelope): boolean {
    const source = event.sourceId ? this.state.actors.get(event.sourceId) : undefined;
    const target = event.targetId ? this.state.actors.get(event.targetId) : undefined;
    const hero = this.state.actors.get("hero");
    for (const condition of rule.conditions) {
      switch (condition.type) {
        case "sourceIsHero":
          if (source?.side !== "hero") return false;
          break;
        case "sourceIsEnemy":
          if (source?.side !== "enemy") return false;
          break;
        case "targetIsEnemy":
          if (target?.side !== "enemy") return false;
          break;
        case "targetIsHero":
          if (target?.side !== "hero") return false;
          break;
        case "targetHasStatus":
          if (!condition.status || !target?.statuses[condition.status]) return false;
          break;
        case "targetMissingStatus":
          if (condition.status && target?.statuses[condition.status]) return false;
          break;
        case "sourceHealthBelowPct":
          if (!source || percentage(source.health, source.maxHealth) >= (condition.pct ?? 0)) return false;
          break;
        case "sourceHealthAbovePct":
          if (!source || percentage(source.health, source.maxHealth) <= (condition.pct ?? 100)) return false;
          break;
        case "everyNthSourceAttack":
          if (!source || source.attackCount % Math.max(1, condition.n ?? 1) !== 0) return false;
          break;
        case "everyNthGlobalEvent": {
          const key = condition.event ?? event.type;
          const next = (this.state.globalCounters[key] ?? 0) + 1;
          this.state.globalCounters[key] = next;
          if (next % Math.max(1, condition.n ?? 1) !== 0) return false;
          break;
        }
        case "eventCritical":
          if (!Boolean(event.payload.critical)) return false;
          break;
        case "eventStatusIs":
          if (String(event.payload.status) !== condition.status) return false;
          break;
        case "eventHasTag":
          if (!condition.tag || !event.tags.includes(condition.tag)) return false;
          break;
        case "targetIsElite":
          if (!target?.elite) return false;
          break;
        case "targetIsBoss":
          if (!target?.bossId) return false;
          break;
        case "heroHasShield":
          if (!hero || hero.shield <= 0) return false;
          break;
        case "overhealPositive":
          if (Number(event.payload.overheal ?? 0) <= 0) return false;
          break;
        case "randomChancePct":
          if (!this.rng.chance(condition.pct ?? 0)) return false;
          break;
      }
    }
    return true;
  }

  private applyEffect(
    rule: RuleDefinition,
    effect: RuleEffect,
    event: EventEnvelope,
    ruleIndex: number,
    scale: number,
  ): void {
    const corrupted =
      this.state.corruptedRuleIndex === ruleIndex && this.state.corruptedUntilTick > this.state.tick;
    const sacrificeSuppressed =
      rule.family === "sacrifice" && this.state.suppressSacrificeUntilTick > this.state.tick;
    const source = event.sourceId ? this.state.actors.get(event.sourceId) : undefined;
    const eventTarget = event.targetId ? this.state.actors.get(event.targetId) : undefined;
    const hero = this.state.actors.get("hero");
    const scaled = (value: number): number => Math.max(0, Math.round(value * scale));

    switch (effect.type) {
      case "modifyDamage": {
        const current = Number(event.payload.amount ?? event.payload.baseDamage ?? 0);
        const multiplier = 100 + (effect.multiplierPct - 100) * scale;
        event.payload.amount = Math.max(
          0,
          Math.round((current * multiplier) / 100 + scaled(effect.flat ?? 0)),
        );
        if (effect.critical) event.payload.critical = true;
        if (effect.tag && !event.tags.includes(effect.tag)) event.tags.push(effect.tag);
        break;
      }
      case "applyStatus": {
        const target = corrupted
          ? hero
          : effect.target === "source"
            ? source
            : effect.target === "hero"
              ? hero
              : eventTarget;
        if (target)
          this.applyStatus(
            target,
            effect.status,
            scaled(effect.durationTicks),
            scaled(effect.potency),
            event.sourceId ?? "hero",
            event,
            rule.id,
            effect.stacks ?? 1,
          );
        break;
      }
      case "applyStatusInRadius": {
        const center = eventTarget?.position ?? source?.position;
        if (!center) break;
        const side = corrupted ? "hero" : "enemy";
        for (const actor of this.actorsInRadius(center, effect.radius, side)) {
          this.applyStatus(
            actor,
            effect.status,
            scaled(effect.durationTicks),
            scaled(effect.potency),
            event.sourceId ?? "hero",
            event,
            rule.id,
            1,
          );
        }
        break;
      }
      case "explode": {
        if (effect.damage === 0 && effect.radius <= 10) {
          if (effect.friendlyFire) event.payload.friendlyFire = true;
          break;
        }
        const targetId = corrupted ? "hero" : event.targetId;
        this.enqueue(
          "ExplosionCreated",
          {
            radius: effect.radius,
            damage: scaled(effect.damage),
            friendlyFire: Boolean(effect.friendlyFire),
            corrupted,
          },
          event.sourceId ?? "hero",
          targetId,
          event,
          rule.id,
          ["explosion"],
        );
        break;
      }
      case "healHero": {
        if (!hero) break;
        const fromDamage = effect.percentOfDamage
          ? (Number(event.payload.amount ?? 0) * effect.percentOfDamage) / 100
          : 0;
        this.enqueue(
          "HealingReceived",
          { amount: scaled(effect.amount + fromDamage) },
          event.sourceId ?? "hero",
          hero.id,
          event,
          rule.id,
          ["heal"],
        );
        break;
      }
      case "shieldHero": {
        if (!hero) break;
        const amount = effect.fromOverheal ? Number(event.payload.overheal ?? 0) : scaled(effect.amount);
        if (amount > 0)
          this.enqueue("ShieldGained", { amount }, event.sourceId ?? "hero", hero.id, event, rule.id, [
            "shield",
          ]);
        break;
      }
      case "selfDamage": {
        if (sacrificeSuppressed || !hero) break;
        const amount = effect.percentMaxHealth
          ? Math.ceil((hero.maxHealth * effect.percentMaxHealth) / 100)
          : scaled(effect.amount);
        this.enqueue("DamageDealt", { amount, critical: false }, "hero", "hero", event, rule.id, [
          "sacrifice",
        ]);
        break;
      }
      case "spawnShards": {
        const center = eventTarget?.position;
        if (!center) break;
        const targets = this.nearestActors(center, "enemy", effect.count, event.targetId);
        targets.forEach((target, index) => {
          const projectile = this.enqueue(
            "ProjectileCreated",
            { damage: scaled(effect.damage), shard: true, index },
            event.sourceId ?? "hero",
            target.id,
            event,
            rule.id,
            ["projectile", "shard"],
          );
          this.enqueue(
            "DamageDealt",
            { amount: scaled(effect.damage), critical: false },
            event.sourceId ?? "hero",
            target.id,
            projectile,
            rule.id,
            ["projectile", "shard"],
          );
          if (effect.applyStatus)
            this.applyStatus(
              target,
              effect.applyStatus,
              70,
              1,
              event.sourceId ?? "hero",
              projectile,
              rule.id,
              1,
            );
        });
        this.enqueue(
          "ShardsCreated",
          { count: targets.length },
          event.sourceId ?? "hero",
          event.targetId,
          event,
          rule.id,
          ["shard"],
        );
        break;
      }
      case "propagateStatus": {
        const center = eventTarget?.position;
        if (!center) break;
        const originStatus = eventTarget?.statuses[effect.status];
        const targets = this.nearestActors(center, "enemy", effect.maxTargets ?? 3, event.targetId).filter(
          (actor) => withinRadius(center, actor.position, effect.radius),
        );
        for (const target of targets) {
          this.applyStatus(
            target,
            effect.status,
            originStatus?.remainingTicks ?? 110,
            originStatus?.potency ?? 3,
            originStatus?.sourceId ?? "hero",
            event,
            rule.id,
            originStatus?.stacks ?? 1,
          );
        }
        break;
      }
      case "shareDamage": {
        if (event.tags.includes("shared")) break;
        const center = eventTarget?.position;
        if (!center) break;
        const amount = scaled((Number(event.payload.amount ?? 0) * effect.pct) / 100);
        for (const target of this.actorsInRadius(center, effect.radius, "enemy").filter(
          (actor) => actor.id !== event.targetId,
        )) {
          this.enqueue(
            "DamageDealt",
            { amount, critical: false },
            event.sourceId ?? "hero",
            target.id,
            event,
            rule.id,
            ["shared"],
          );
        }
        break;
      }
      case "summonServant":
        this.summonServant(effect.durationTicks, effect.damagePct, event, rule.id);
        break;
      case "gainInk": {
        const amount = scaled(effect.amount);
        this.state.ink = Math.min(this.state.maxInk, this.state.ink + amount);
        this.enqueue("InkGained", { amount }, event.sourceId ?? "hero", "hero", event, rule.id, ["ink"]);
        break;
      }
      case "reduceCooldown":
        if (hero) hero.cooldownRemaining = Math.max(0, hero.cooldownRemaining - scaled(effect.ticks));
        break;
      case "doubleHit": {
        if (!event.targetId || event.tags.includes("double-hit")) break;
        const amount = Math.max(
          1,
          Math.round(
            (Number(event.payload.amount ?? event.payload.baseDamage ?? 0) * effect.multiplierPct * scale) /
              100,
          ),
        );
        this.enqueue(
          "DamageDealt",
          { amount, critical: false },
          event.sourceId ?? "hero",
          event.targetId,
          event,
          rule.id,
          ["double-hit", "direct"],
        );
        break;
      }
      case "reviveHero": {
        if (!hero || hero.alive || this.state.globalCounters.heroRevived) break;
        hero.alive = true;
        hero.health = Math.max(1, Math.round((hero.maxHealth * effect.healthPct) / 100));
        this.deathQueued.delete(hero.id);
        this.state.globalCounters.heroRevived = 1;
        if (effect.destroyRule) this.permanentlyConsumedRules.add(rule.id);
        this.enqueue(
          "HealingReceived",
          { amount: hero.health, revive: true },
          "hero",
          hero.id,
          event,
          rule.id,
          ["revive"],
        );
        break;
      }
      case "resetHeroCooldown":
        if (hero) hero.cooldownRemaining = 0;
        break;
      case "convertPoisonCritical": {
        this.state.globalCounters.poisonCriticalChance = Math.max(
          this.state.globalCounters.poisonCriticalChance ?? 0,
          scaled(effect.chancePct),
        );
        const status = eventTarget?.statuses.poison;
        if (status)
          status.remainingTicks = Math.max(
            1,
            Math.round((status.remainingTicks * effect.durationMultiplierPct) / 100),
          );
        break;
      }
      case "reduceEnemyDamage": {
        if (event.type !== "AttackStarted" || source?.side !== "enemy") break;
        if (effect.requiresStatus && !source.statuses[effect.requiresStatus]) break;
        const amount = Number(event.payload.amount ?? 0);
        event.payload.amount = Math.max(0, Math.round((amount * (100 - scaled(effect.pct))) / 100));
        break;
      }
      case "addProjectileBounce": {
        if (!eventTarget || event.tags.includes("bounce")) break;
        const next = this.nearestActors(eventTarget.position, "enemy", 1, eventTarget.id)[0];
        if (!next) break;
        const amount = Math.max(1, Number(event.payload.damage ?? event.payload.amount ?? 12));
        this.enqueue(
          "DamageDealt",
          { amount, critical: false },
          event.sourceId ?? "hero",
          next.id,
          event,
          rule.id,
          ["projectile", "bounce"],
        );
        break;
      }
      case "spawnHealingOrb":
        if (hero)
          this.enqueue(
            "HealingReceived",
            { amount: scaled(effect.amount), orb: true },
            event.sourceId ?? "hero",
            hero.id,
            event,
            rule.id,
            ["heal", "orb"],
          );
        break;
      case "chainDamage": {
        const origin = eventTarget?.position;
        if (!origin) break;
        const targets = this.nearestActors(origin, "enemy", effect.jumps, event.targetId).filter((actor) =>
          withinRadius(origin, actor.position, effect.radius),
        );
        targets.forEach((target, index) =>
          this.enqueue(
            "DamageDealt",
            { amount: scaled(effect.damage), critical: false, jump: index + 1 },
            event.sourceId ?? "hero",
            target.id,
            event,
            rule.id,
            ["chain-lightning"],
          ),
        );
        break;
      }
      case "goldBurst":
        this.state.goldEarned += scaled(effect.amount);
        break;
      case "upgradeRandomStatus": {
        if (rule.id === "friendly-pyre" && event.type === "ExplosionCreated") {
          const damage = Number(event.payload.damage ?? 0);
          event.payload.damage = Math.round((damage * (100 + effect.amount * scale)) / 100);
          event.payload.friendlyFire = !sacrificeSuppressed;
        } else if (
          rule.id === "red-editor" &&
          event.type === "RuleTriggered" &&
          !event.tags.includes("echoed")
        ) {
          const causedRuleId = String(event.payload.ruleId ?? "");
          const caused = RULE_BY_ID.get(causedRuleId);
          const sourceEventId = Number(event.payload.sourceEventId ?? -1);
          const original = this.history.find((candidate) => candidate.id === sourceEventId);
          if (caused && original && caused.id !== rule.id) {
            const echoEvent = { ...original, tags: [...original.tags, "echoed"] };
            caused.effects
              .slice(0, 1)
              .forEach((nested) =>
                this.applyEffect(caused, nested, echoEvent, ruleIndex, effect.amount / 100),
              );
          }
        }
        break;
      }
    }
  }

  private applyEvent(event: EventEnvelope): void {
    const source = event.sourceId ? this.state.actors.get(event.sourceId) : undefined;
    const target = event.targetId ? this.state.actors.get(event.targetId) : undefined;
    switch (event.type) {
      case "AttackStarted": {
        if (!event.sourceId || !event.targetId || !source?.alive || !target?.alive) break;
        const amount = Math.max(0, Math.round(Number(event.payload.amount ?? event.payload.baseDamage ?? 0)));
        if (Boolean(event.payload.projectile)) {
          const projectile = this.enqueue(
            "ProjectileCreated",
            { damage: amount, critical: Boolean(event.payload.critical) },
            source.id,
            target.id,
            event,
            event.causeRuleId,
            ["projectile"],
          );
          this.enqueue(
            "DamageDealt",
            { amount, critical: Boolean(event.payload.critical) },
            source.id,
            target.id,
            projectile,
            event.causeRuleId,
            ["direct", "projectile"],
          );
        } else {
          this.enqueue(
            "DamageDealt",
            { amount, critical: Boolean(event.payload.critical) },
            source.id,
            target.id,
            event,
            event.causeRuleId,
            ["direct", "melee"],
          );
        }
        if (Boolean(event.payload.critical))
          this.enqueue("CriticalHit", { amount }, source.id, target.id, event, event.causeRuleId, [
            "critical",
          ]);
        break;
      }
      case "StatusTick": {
        if (!event.sourceId || !event.targetId || !target?.alive) break;
        this.enqueue(
          "DamageDealt",
          { amount: Number(event.payload.amount ?? 0), critical: Boolean(event.payload.critical) },
          event.sourceId,
          event.targetId,
          event,
          event.causeRuleId,
          ["status", String(event.payload.status ?? "")],
        );
        break;
      }
      case "DamageDealt":
        this.applyDamage(event, source, target);
        break;
      case "HealingReceived": {
        if (!target?.alive) break;
        const amount = Math.max(0, Math.round(Number(event.payload.amount ?? 0)));
        const before = target.health;
        target.health = Math.min(target.maxHealth, target.health + amount);
        const applied = target.health - before;
        event.payload.applied = applied;
        event.payload.overheal = Math.max(0, amount - applied);
        if (target.side === "hero") this.metrics.healingReceived += applied;
        break;
      }
      case "ShieldGained": {
        if (!target?.alive) break;
        const amount = Math.max(0, Math.round(Number(event.payload.amount ?? 0)));
        target.shield += amount;
        break;
      }
      case "ExplosionCreated":
        this.applyExplosion(event);
        break;
      case "EnemyKilled":
        this.resolveEnemyDeath(event, target);
        break;
      case "AllyKilled":
        if (target && target.side !== "enemy") target.alive = false;
        break;
      default:
        break;
    }
  }

  private applyDamage(
    event: EventEnvelope,
    source: CombatActor | undefined,
    target: CombatActor | undefined,
  ): void {
    if (!target?.alive) return;
    let amount = Math.max(0, Math.round(Number(event.payload.amount ?? 0)));
    const vulnerability = target.statuses.vulnerability?.potency ?? 0;
    amount = Math.round((amount * (100 + vulnerability)) / 100);
    if (target.shield > 0 && amount > 0) {
      const absorbed = Math.min(target.shield, amount);
      target.shield -= absorbed;
      amount -= absorbed;
      event.payload.absorbed = absorbed;
      if (target.shield === 0)
        this.enqueue("ShieldBroken", { absorbed }, source?.id, target.id, event, event.causeRuleId, [
          "shield",
        ]);
    }
    if (amount > 0) target.health = Math.max(0, target.health - amount);
    event.payload.applied = amount;
    if (source?.side === "hero" || source?.side === "ally") this.metrics.damageDealt += amount;
    if (target.side === "hero") this.metrics.damageTaken += amount;

    if (target.health <= 0 && !this.deathQueued.has(target.id)) {
      this.deathQueued.add(target.id);
      target.alive = false;
      const type = target.side === "enemy" ? "EnemyKilled" : "AllyKilled";
      this.enqueue(
        type,
        { elite: target.elite, bossId: target.bossId },
        source?.id,
        target.id,
        event,
        event.causeRuleId,
        ["death"],
      );
    }
  }

  private applyExplosion(event: EventEnvelope): void {
    const centerActor = event.targetId ? this.state.actors.get(event.targetId) : undefined;
    const center = centerActor?.position ?? { x: 0, z: 0 };
    const radius = Math.max(0, Number(event.payload.radius ?? 0));
    const damage = Math.max(0, Math.round(Number(event.payload.damage ?? 0)));
    const friendlyFire = Boolean(event.payload.friendlyFire);
    if (radius <= 0 || damage <= 0) return;
    for (const actor of [...this.state.actors.values()].sort((a, b) => a.id.localeCompare(b.id))) {
      if (!actor.alive || actor.id === event.targetId || !withinRadius(center, actor.position, radius))
        continue;
      if (actor.side === "enemy" || (friendlyFire && actor.side === "hero")) {
        this.enqueue(
          "DamageDealt",
          { amount: damage, critical: false },
          event.sourceId ?? "hero",
          actor.id,
          event,
          event.causeRuleId,
          ["explosion"],
        );
      }
    }
  }

  private resolveEnemyDeath(event: EventEnvelope, target: CombatActor | undefined): void {
    if (!target) return;
    target.alive = false;
    this.metrics.enemiesKilled += 1;
    if (target.elite) this.metrics.elitesKilled += 1;
    const definition = ENEMY_BY_ID.get(target.definitionId);
    const gold = definition?.gold ?? 4;
    this.state.goldEarned += gold;
    this.state.ink = Math.min(this.state.maxInk, this.state.ink + (target.elite ? 10 : 2));
    this.enqueue(
      "GoldDropped",
      { amount: gold },
      event.sourceId ?? "hero",
      target.id,
      event,
      event.causeRuleId,
      ["gold"],
    );

    if (this.config.heroClass.passive === "widow" && this.metrics.enemiesKilled % 4 === 0)
      this.summonServant(220, 40, event, "class-widow");
    if (this.config.heroClass.passive === "ash") {
      const hero = this.state.actors.get("hero");
      if (hero?.alive)
        this.enqueue("HealingReceived", { amount: 5 }, "hero", hero.id, event, "class-ash", [
          "class-passive",
        ]);
    }
  }

  private applyStatus(
    target: CombatActor,
    kind: StatusKind,
    durationTicks: number,
    potency: number,
    sourceId: EntityId,
    parent: EventEnvelope,
    causeRuleId: RuleId,
    stacks: number,
  ): void {
    if (!target.alive) return;
    const resistance = target.resistances[kind] ?? 0;
    const effectiveDuration = Math.max(1, Math.round((durationTicks * (100 - resistance)) / 100));
    if (effectiveDuration <= 1 && resistance >= 100) return;
    const existing = target.statuses[kind];
    const status: StatusInstance = {
      kind,
      remainingTicks: Math.max(existing?.remainingTicks ?? 0, effectiveDuration),
      potency: Math.max(existing?.potency ?? 0, potency),
      stacks: Math.min(9, (existing?.stacks ?? 0) + Math.max(1, stacks)),
      sourceId,
    };
    target.statuses[kind] = status;
    this.enqueue(
      "StatusApplied",
      { status: kind, durationTicks: status.remainingTicks, potency: status.potency, stacks: status.stacks },
      sourceId,
      target.id,
      parent,
      causeRuleId,
      ["status", kind],
    );
  }

  private summonServant(
    durationTicks: number,
    damagePct: number,
    parent: EventEnvelope,
    causeRuleId: RuleId,
  ): void {
    const hero = this.state.actors.get("hero");
    if (!hero?.alive) return;
    const id = `servant-${this.state.nextActorSerial++}`;
    const angle = this.rng.nextFloat() * Math.PI * 2;
    const actor: CombatActor = {
      id,
      definitionId: "void-servant",
      displayName: "Serviteur du Codex",
      side: "ally",
      behavior: "servant",
      position: {
        x: hero.position.x + Math.round(Math.cos(angle) * 75),
        z: hero.position.z + Math.round(Math.sin(angle) * 75),
      },
      health: 1,
      maxHealth: 1,
      shield: 0,
      speedPerTick: 21,
      attackDamage: Math.max(4, Math.round((hero.attackDamage * damagePct) / 100)),
      attackRange: 240,
      attackCooldownTicks: 24,
      cooldownRemaining: 5,
      attackCount: 0,
      dodgeChancePct: 100,
      critChancePct: 0,
      alive: true,
      elite: false,
      threat: 1,
      statuses: {},
      resistances: {},
      expiresAtTick: this.state.tick + durationTicks,
      phase: 1,
    };
    this.state.actors.set(id, actor);
    this.enqueue(
      "ActorSummoned",
      { durationTicks, damage: actor.attackDamage },
      "hero",
      id,
      parent,
      causeRuleId,
      ["summon"],
    );
  }

  private forceTriggerRule(index: number, ruleId: RuleId): void {
    const rule = getRule(ruleId);
    const hero = this.state.actors.get("hero");
    const target = hero ? this.selectTarget(hero) : undefined;
    const payload: Record<string, unknown> = {
      baseDamage: hero?.attackDamage ?? 0,
      amount: hero?.attackDamage ?? 0,
      critical: false,
      status: target ? Object.keys(target.statuses)[0] : undefined,
      manual: true,
    };
    this.enqueue(rule.trigger, payload, "hero", target?.id ?? "hero", undefined, undefined, [
      `manual:${ruleId}`,
      `manual-index:${index}`,
    ]);
  }

  private consumeCodexSlot(count: number, boss: CombatActor): void {
    const index = this.state.codexOrder.length - count;
    const ruleId = this.state.codexOrder[index];
    if (!ruleId) return;
    this.state.disabledRuleUntil[index] = Number.MAX_SAFE_INTEGER;
    this.enqueue(
      "BossMechanic",
      { bossId: boss.bossId, kind: "devour", ruleId, index },
      boss.id,
      "hero",
      undefined,
      undefined,
      ["boss", "codex"],
    );
  }

  private inquisitorCensure(boss: CombatActor): void {
    const entries = this.state.codexOrder
      .map((ruleId, index) => ({ ruleId, index, count: this.state.ruleTriggerCounts[ruleId] ?? 0 }))
      .sort((a, b) => b.count - a.count || a.index - b.index);
    const target = entries[0];
    if (!target) return;
    this.state.disabledRuleUntil[target.index] = this.state.tick + 150;
    this.enqueue(
      "BossMechanic",
      {
        bossId: boss.bossId,
        kind: "censure",
        ruleId: target.ruleId,
        index: target.index,
        durationTicks: 150,
      },
      boss.id,
      "hero",
      undefined,
      undefined,
      ["boss", "codex"],
    );
  }

  private judgeCopiesFirstRule(boss: CombatActor): void {
    const ruleId = this.state.codexOrder[0];
    if (!ruleId) return;
    const rule = getRule(ruleId);
    const hero = this.state.actors.get("hero");
    if (!hero?.alive) return;
    let amount = Math.round(boss.attackDamage * 1.4);
    if (rule.family === "sacrifice") amount = Math.round(amount * 1.35);
    this.enqueue(
      "BossMechanic",
      { bossId: boss.bossId, kind: "copy", ruleId, ruleName: rule.name },
      boss.id,
      hero.id,
      undefined,
      undefined,
      ["boss", "codex"],
    );
    this.enqueue(
      "DamageDealt",
      { amount, critical: rule.tags.includes("critical") },
      boss.id,
      hero.id,
      undefined,
      ruleId,
      ["boss-copy"],
    );
    if (rule.tags.includes("burn"))
      this.applyStatus(
        hero,
        "burn",
        100,
        4,
        boss.id,
        this.history.at(-1) ?? this.enqueue("BossMechanic", {}, boss.id, hero.id),
        ruleId,
        1,
      );
    if (rule.tags.includes("poison"))
      this.applyStatus(
        hero,
        "poison",
        120,
        3,
        boss.id,
        this.history.at(-1) ?? this.enqueue("BossMechanic", {}, boss.id, hero.id),
        ruleId,
        1,
      );
  }

  private corruptRule(boss: CombatActor, durationTicks: number): void {
    const available = this.state.codexOrder
      .map((_, index) => index)
      .filter((index) => !this.isRuleDisabled(index));
    if (available.length === 0) return;
    const index = this.rng.pick(available);
    this.state.corruptedRuleIndex = index;
    this.state.corruptedUntilTick = this.state.tick + durationTicks;
    this.enqueue(
      "BossMechanic",
      { bossId: boss.bossId, kind: "corrupt", index, ruleId: this.state.codexOrder[index], durationTicks },
      boss.id,
      "hero",
      undefined,
      undefined,
      ["boss", "codex", "corruption"],
    );
  }

  private actorsInRadius(
    center: { x: number; z: number },
    radius: number,
    side: "hero" | "enemy" | "ally",
  ): CombatActor[] {
    return [...this.state.actors.values()]
      .filter((actor) => actor.alive && actor.side === side && withinRadius(center, actor.position, radius))
      .sort(
        (a, b) =>
          distanceSquared(center, a.position) - distanceSquared(center, b.position) ||
          a.id.localeCompare(b.id),
      );
  }

  private nearestActors(
    center: { x: number; z: number },
    side: "hero" | "enemy" | "ally",
    count: number,
    excludeId?: string,
  ): CombatActor[] {
    return [...this.state.actors.values()]
      .filter((actor) => actor.alive && actor.side === side && actor.id !== excludeId)
      .sort(
        (a, b) =>
          distanceSquared(center, a.position) - distanceSquared(center, b.position) ||
          a.id.localeCompare(b.id),
      )
      .slice(0, Math.max(0, count));
  }

  private ruleScale(ruleId: RuleId): number {
    return 1 + Math.max(0, (this.ruleLevels.get(ruleId) ?? 1) - 1) * 0.25;
  }

  private isRuleDisabled(index: number): boolean {
    return (this.state.disabledRuleUntil[index] ?? 0) > this.state.tick;
  }

  private getRewriteCost(kind: RewriteKind): number {
    return Math.max(1, Math.round((BASE_REWRITE_COSTS[kind] * this.config.rewriteCostMultiplierPct) / 100));
  }

  private record(event: EventEnvelope): void {
    this.history.push(event);
    if (this.history.length > EVENT_HISTORY_LIMIT)
      this.history.splice(0, this.history.length - EVENT_HISTORY_LIMIT);
  }

  private evaluateCombatEnd(): void {
    if (this.state.status !== "running") return;
    const hero = this.state.actors.get("hero");
    const enemyAlive = [...this.state.actors.values()].some((actor) => actor.side === "enemy" && actor.alive);
    if (!hero?.alive || !enemyAlive) {
      const activeRewrites = [...this.state.activeRewrites].reverse();
      for (const rewrite of activeRewrites) {
        if (rewrite.kind === "swap" && rewrite.previousOrder)
          this.state.codexOrder = [...rewrite.previousOrder];
        if (rewrite.kind === "retarget" && rewrite.previousTargeting)
          this.state.targetingMode = rewrite.previousTargeting;
      }
      this.state.activeRewrites = [];
      this.state.copiedRule = undefined;
      this.state.suppressSacrificeUntilTick = 0;
    }
    if (!hero?.alive) {
      this.state.status = "defeat";
      this.state.resultReason = "Le Pénitent a été effacé.";
      this.enqueue(
        "CombatEnded",
        { result: "defeat", reason: this.state.resultReason },
        undefined,
        "hero",
        undefined,
        undefined,
        ["combat-end"],
      );
      this.resolveQueue();
    } else if (!enemyAlive) {
      this.state.status = "victory";
      this.state.resultReason = "La salle obéit désormais à votre Codex.";
      this.enqueue(
        "CombatEnded",
        { result: "victory", reason: this.state.resultReason },
        "hero",
        undefined,
        undefined,
        undefined,
        ["combat-end"],
      );
      this.resolveQueue();
    }
  }
}

function nextTargetingMode(current: TargetingMode): TargetingMode {
  const modes: TargetingMode[] = ["nearest", "lowest-health", "highest-health", "ranged-first"];
  const index = modes.indexOf(current);
  return modes[(index + 1) % modes.length] ?? "nearest";
}

function rewriteMessage(kind: RewriteKind, request: RewriteRequest): string {
  switch (kind) {
    case "swap":
      return `Règles ${(request.firstIndex ?? 0) + 1} et ${(request.secondIndex ?? 1) + 1} inversées.`;
    case "disable":
      return `Règle ${(request.ruleIndex ?? 0) + 1} suspendue.`;
    case "trigger":
      return `Règle ${(request.ruleIndex ?? 0) + 1} déclenchée immédiatement.`;
    case "copy":
      return `Règle ${(request.ruleIndex ?? 0) + 1} copiée temporairement.`;
    case "retarget":
      return `Ciblage réécrit vers ${request.targetingMode ?? "une nouvelle priorité"}.`;
    case "suppress-sacrifice":
      return "Les contreparties des Lois du sacrifice sont annulées.";
  }
}
