import { createDefaultMeta, generateNodes } from "../domain/run";
import { hashString } from "../domain/rng";
import type { GameSettings, MetaProgress, RunState } from "../domain/types";

const META_KEY = "rota.meta.v1";
const RUN_KEY = "rota.run.v1";
const SETTINGS_KEY = "rota.settings.v1";

export function defaultSettings(): GameSettings {
  return {
    version: 1,
    masterVolume: 0.72,
    effectsVolume: 0.78,
    reducedMotion: false,
    reducedVfx: false,
    highContrast: false,
    showDamageNumbers: true,
    gameSpeed: 1,
    language: "fr",
  };
}

export function loadMeta(storage: Storage | undefined = safeStorage()): MetaProgress {
  const fallback = createDefaultMeta();
  if (!storage) return fallback;
  try {
    const parsed = JSON.parse(storage.getItem(META_KEY) ?? "null") as Partial<MetaProgress> | null;
    if (!parsed || parsed.version !== 1) return fallback;
    return {
      ...fallback,
      ...parsed,
      unlockedClassIds: [...new Set(parsed.unlockedClassIds ?? fallback.unlockedClassIds)],
      unlockedRuleIds: [...new Set(parsed.unlockedRuleIds ?? fallback.unlockedRuleIds)],
      discoveredRuleIds: [...new Set(parsed.discoveredRuleIds ?? fallback.discoveredRuleIds)],
      achievements: [...new Set(parsed.achievements ?? fallback.achievements)],
    };
  } catch {
    return fallback;
  }
}

export function saveMeta(meta: MetaProgress, storage: Storage | undefined = safeStorage()): void {
  try {
    storage?.setItem(META_KEY, JSON.stringify(meta));
  } catch {
    /* localStorage peut être indisponible */
  }
}

export function loadRun(storage: Storage | undefined = safeStorage()): RunState | undefined {
  if (!storage) return undefined;
  try {
    const parsed = JSON.parse(storage.getItem(RUN_KEY) ?? "null") as
      | (RunState & { routeKey?: number })
      | null;
    if (!parsed || parsed.version !== 1 || !parsed.classId || !Array.isArray(parsed.ownedRules))
      return undefined;
    if (!Number.isInteger(parsed.routeKey))
      parsed.routeKey = hashString(`${parsed.seed >>> 0}:route:origin`) >>> 0;
    if (!Array.isArray(parsed.availableNodes)) parsed.availableNodes = generateNodes(parsed as RunState);
    return parsed as RunState;
  } catch {
    return undefined;
  }
}

export function saveRun(run: RunState | undefined, storage: Storage | undefined = safeStorage()): void {
  try {
    if (!run) storage?.removeItem(RUN_KEY);
    else storage?.setItem(RUN_KEY, JSON.stringify(run));
  } catch {
    /* localStorage peut être indisponible */
  }
}

export function loadSettings(storage: Storage | undefined = safeStorage()): GameSettings {
  const fallback = defaultSettings();
  if (!storage) return fallback;
  try {
    const parsed = JSON.parse(storage.getItem(SETTINGS_KEY) ?? "null") as Partial<GameSettings> | null;
    if (!parsed || parsed.version !== 1) return fallback;
    return { ...fallback, ...parsed, version: 1, language: "fr" };
  } catch {
    return fallback;
  }
}

export function saveSettings(settings: GameSettings, storage: Storage | undefined = safeStorage()): void {
  try {
    storage?.setItem(SETTINGS_KEY, JSON.stringify(settings));
  } catch {
    /* localStorage peut être indisponible */
  }
}

export function clearAllSaves(storage: Storage | undefined = safeStorage()): void {
  try {
    storage?.removeItem(META_KEY);
    storage?.removeItem(RUN_KEY);
    storage?.removeItem(SETTINGS_KEY);
  } catch {
    /* localStorage peut être indisponible */
  }
}

function safeStorage(): Storage | undefined {
  try {
    return typeof window === "undefined" ? undefined : window.localStorage;
  } catch {
    return undefined;
  }
}
