import { HERO_CLASSES, RULES, getHeroClass } from "../content/gameContent";
import { CombatSimulation } from "../domain/combat";
import {
  activateRule,
  applyEventChoice,
  applyReward,
  applySanctuaryAction,
  buildEncounter,
  buyShopOffer,
  chooseRunEvent,
  createRun,
  deactivateRule,
  finishRoom,
  generateBranchPreviews,
  generateRewardOptions,
  generateShopOffers,
  recordCombatResult,
  setCodexOrder,
  updateMetaAfterRun,
} from "../domain/run";
import {
  clearAllSaves,
  loadMeta,
  loadRun,
  loadSettings,
  saveMeta,
  saveRun,
  saveSettings,
} from "./persistence";
import type {
  EventChoice,
  GameScreen,
  GameSettings,
  HeroClassId,
  RewriteKind,
  RoomType,
  RuleId,
  RuntimeSnapshot,
  ShopOffer,
  TargetingMode,
} from "../domain/types";
import { BabylonGameView } from "../presentation/babylon/BabylonGameView";
import { AudioSystem } from "./AudioSystem";

interface RewriteRequest {
  firstIndex?: number;
  secondIndex?: number;
  ruleIndex?: number;
  targetingMode?: TargetingMode;
}

export class GameRuntime {
  private readonly view: BabylonGameView;
  private readonly audio: AudioSystem;
  private screen: GameScreen = "boot";
  private previousScreen?: GameScreen;
  private run = loadRun();
  private meta = loadMeta();
  private settings = loadSettings();
  private combat?: CombatSimulation;
  private rewardOptions: RuntimeSnapshot["rewardOptions"] = [];
  private shopOffers: ShopOffer[] = [];
  private currentEvent?: RuntimeSnapshot["currentEvent"];
  private message?: string;
  private messageId = 0;
  private paused = false;
  private rewriteSuspendedCombat = false;
  private animationFrame = 0;
  private lastFrameTime = 0;
  private accumulator = 0;
  private lastEventSequence = 0;
  private combatRecorded = false;
  private disposed = false;

  public constructor(
    canvas: HTMLCanvasElement,
    private readonly onSnapshot: (snapshot: RuntimeSnapshot) => void,
  ) {
    this.view = new BabylonGameView(canvas);
    this.audio = new AudioSystem(this.settings);
  }

  public async initialize(): Promise<void> {
    await this.view.initialize();
    if (this.disposed) return;
    this.view.updateSettings(this.settings);
    this.screen = "menu";
    this.emitSnapshot();
    this.animationFrame = requestAnimationFrame(this.frame);
  }

  public async unlockAudio(): Promise<void> {
    await this.audio.unlock();
  }

  public openClassSelect(): void {
    this.leaveCombatView();
    this.previousScreen = this.screen;
    this.screen = "class-select";
    this.clearMessage();
    this.emitSnapshot();
  }

  public openEncyclopedia(): void {
    this.previousScreen = this.screen;
    this.screen = "encyclopedia";
    this.emitSnapshot();
  }

  public continueSavedRun(): void {
    const saved = loadRun();
    if (!saved) {
      this.showMessage("Aucune partie sauvegardée.");
      this.emitSnapshot();
      return;
    }
    this.run = saved;
    this.screen = "map";
    this.showMessage("Partie restaurée.");
    this.emitSnapshot();
  }

  public startNewRun(classId: HeroClassId, difficulty = 0): boolean {
    if (!this.meta.unlockedClassIds.includes(classId)) return false;
    const requestedSeed = Number(new URLSearchParams(window.location.search).get("seed"));
    const seed =
      Number.isInteger(requestedSeed) && requestedSeed > 0
        ? requestedSeed >>> 0
        : (Date.now() ^ Math.floor(Math.random() * 0x7fffffff)) >>> 0;
    this.run = createRun(seed, classId, difficulty);
    this.screen = "map";
    this.showMessage(`${getHeroClass(classId).name} ouvre le Codex.`);
    saveRun(this.run);
    this.emitSnapshot();
    return true;
  }

  public chooseNode(nodeId: string): boolean {
    const run = this.run;
    if (!run) return false;
    const node = run.availableNodes.find((candidate) => candidate.id === nodeId);
    if (!node) return false;
    run.currentNode = { ...node };
    this.clearMessage();
    if (node.type === "combat" || node.type === "elite" || node.type === "boss") {
      this.startCombat(node.type);
    } else if (node.type === "shop") {
      this.shopOffers = generateShopOffers(run);
      this.screen = "shop";
    } else if (node.type === "event") {
      this.currentEvent = chooseRunEvent(run);
      this.screen = "event";
    } else {
      this.screen = "sanctuary";
    }
    saveRun(run);
    this.emitSnapshot();
    return true;
  }

  public startCombatNow(): void {
    this.combat?.start();
    this.paused = false;
    this.rewriteSuspendedCombat = false;
    this.emitSnapshot();
  }

  public movePreparedRule(index: number, direction: -1 | 1): boolean {
    const run = this.run;
    const combat = this.combat;
    if (!run || !combat || this.screen !== "combat" || combat.getSnapshot().status !== "ready") return false;
    const next = index + direction;
    if (!run.activeRuleIds[index] || next < 0 || next >= run.activeRuleIds.length) return false;
    const order = [...run.activeRuleIds];
    [order[index], order[next]] = [order[next] as RuleId, order[index] as RuleId];
    if (!setCodexOrder(run, order) || !combat.setReadyCodexOrder(order)) return false;
    saveRun(run);
    this.emitSnapshot();
    return true;
  }

  public setPreparedTargeting(mode: TargetingMode): boolean {
    if (!this.combat || this.screen !== "combat") return false;
    const changed = this.combat.setReadyTargetingMode(mode);
    if (changed) this.emitSnapshot();
    return changed;
  }

  public beginRewrite(): boolean {
    if (!this.combat || this.screen !== "combat") return false;
    const status = this.combat.getSnapshot().status;
    if (status === "running") {
      this.combat.pause();
      this.paused = true;
      this.rewriteSuspendedCombat = true;
    } else if (status === "paused") {
      this.rewriteSuspendedCombat = false;
    } else {
      return false;
    }
    this.emitSnapshot();
    return true;
  }

  public endRewrite(resume = true): void {
    if (!this.combat || this.screen !== "combat") {
      this.rewriteSuspendedCombat = false;
      return;
    }
    if (resume && this.rewriteSuspendedCombat && this.combat.getSnapshot().status === "paused") {
      this.combat.start();
      this.paused = false;
    }
    this.rewriteSuspendedCombat = false;
    this.emitSnapshot();
  }

  public dismissMessage(messageId = this.messageId): void {
    if (messageId !== this.messageId || !this.message) return;
    this.clearMessage();
    this.emitSnapshot();
  }

  public togglePause(): void {
    if (!this.combat || this.screen !== "combat") return;
    const snapshot = this.combat.getSnapshot();
    if (snapshot.status === "running") {
      this.combat.pause();
      this.paused = true;
      this.rewriteSuspendedCombat = false;
    } else if (snapshot.status === "paused") {
      this.combat.start();
      this.paused = false;
      this.rewriteSuspendedCombat = false;
    }
    this.emitSnapshot();
  }

  public rewrite(kind: RewriteKind, request: RewriteRequest = {}): boolean {
    const result = this.combat?.requestRewrite(kind, request) ?? false;
    this.emitSnapshot();
    return result;
  }

  public continueAfterCombat(): void {
    if (!this.combat || !this.run) return;
    const status = this.combat.getSnapshot().status;
    if (status === "defeat") {
      this.completeRun(false);
      return;
    }
    if (status !== "victory") return;
    this.recordCombatOnce();
    const tier = this.combat.getSnapshot().encounter.rewardTier;
    this.rewardOptions = generateRewardOptions(this.run, tier);
    this.screen = "reward";
    this.leaveCombatView();
    this.emitSnapshot();
  }

  public chooseReward(optionId: string): boolean {
    const run = this.run;
    const option = this.rewardOptions.find((entry) => entry.id === optionId);
    if (!run || !option) return false;
    applyReward(run, option);
    this.rewardOptions = [];
    const outcome = finishRoom(run);
    if (outcome === "victory") this.completeRun(true);
    else {
      this.screen = "map";
      this.showMessage(`${option.title} rejoint le Codex.`);
      saveRun(run);
      this.emitSnapshot();
    }
    return true;
  }

  public buyOffer(offerId: string): boolean {
    const run = this.run;
    const offer = this.shopOffers.find((entry) => entry.id === offerId);
    if (!run || !offer) return false;
    const success = buyShopOffer(run, offer);
    if (success) {
      this.showMessage(`${offer.title} acquis.`);
      saveRun(run);
      this.emitSnapshot();
    }
    return success;
  }

  public leaveShop(): void {
    this.finishNonCombatRoom("Le Relieur referme son registre.");
  }

  public chooseEvent(choiceId: string): boolean {
    const run = this.run;
    const event = this.currentEvent;
    const choice = event?.choices.find((entry) => entry.id === choiceId);
    if (!run || !event || !choice) return false;
    const result = applyEventChoice(run, event.id, choice as EventChoice);
    if (!result.success) return false;
    const rewardName = result.rewardRuleId
      ? RULES.find((entry) => entry.id === result.rewardRuleId)?.name
      : undefined;
    this.currentEvent = undefined;
    this.finishNonCombatRoom(rewardName ? `${rewardName} a été inscrit.` : choice.description);
    return true;
  }

  public sanctuary(action: "heal" | "upgrade" | "purge" | "ink", ruleId?: RuleId): boolean {
    const run = this.run;
    if (!run || !applySanctuaryAction(run, action, ruleId)) return false;
    this.finishNonCombatRoom("Le sanctuaire se tait derrière vous.");
    return true;
  }

  public openCodex(): void {
    if (!this.run) return;
    this.previousScreen = this.screen;
    this.screen = "codex";
    this.emitSnapshot();
  }

  public closeOverlayScreen(): void {
    const target = this.previousScreen ?? (this.run ? "map" : "menu");
    this.screen = target;
    this.previousScreen = undefined;
    this.emitSnapshot();
  }

  public moveActiveRule(index: number, direction: -1 | 1): boolean {
    const run = this.run;
    if (!run) return false;
    const next = index + direction;
    if (!run.activeRuleIds[index] || next < 0 || next >= run.activeRuleIds.length) return false;
    const order = [...run.activeRuleIds];
    [order[index], order[next]] = [order[next] as RuleId, order[index] as RuleId];
    const result = setCodexOrder(run, order);
    if (result) {
      saveRun(run);
      this.emitSnapshot();
    }
    return result;
  }

  public activateRule(ruleId: RuleId): boolean {
    if (!this.run || !activateRule(this.run, ruleId)) return false;
    saveRun(this.run);
    this.emitSnapshot();
    return true;
  }

  public deactivateRule(ruleId: RuleId): boolean {
    if (!this.run || !deactivateRule(this.run, ruleId)) return false;
    saveRun(this.run);
    this.emitSnapshot();
    return true;
  }

  public updateSettings(patch: Partial<GameSettings>): void {
    this.settings = { ...this.settings, ...patch, version: 1, language: "fr" };
    this.audio.updateSettings(this.settings);
    this.view.updateSettings(this.settings);
    saveSettings(this.settings);
    this.emitSnapshot();
  }

  public abandonRun(): void {
    if (this.run) updateMetaAfterRun(this.meta, this.run, false);
    this.run = undefined;
    this.combat = undefined;
    this.screen = "menu";
    this.showMessage("La marche a été abandonnée.");
    saveRun(undefined);
    saveMeta(this.meta);
    this.view.clearCombat();
    this.emitSnapshot();
  }

  public returnToMenu(): void {
    const completedRun = this.screen === "run-end";
    this.leaveCombatView();
    if (completedRun) this.run = undefined;
    this.screen = "menu";
    this.previousScreen = undefined;
    this.clearMessage();
    this.emitSnapshot();
  }

  public resetProgress(): void {
    clearAllSaves();
    this.meta = loadMeta();
    this.settings = loadSettings();
    this.run = undefined;
    this.combat = undefined;
    this.screen = "menu";
    this.view.clearCombat();
    this.emitSnapshot();
  }

  public dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    cancelAnimationFrame(this.animationFrame);
    this.audio.dispose();
    this.view.dispose();
  }

  private startCombat(_type: RoomType): void {
    const run = this.run;
    const node = run?.currentNode;
    if (!run || !node) return;
    const encounter = buildEncounter(run, node);
    this.combat = new CombatSimulation({
      seed: run.seed ^ (run.chapter * 10_007 + run.depth * 7919),
      tickRate: 20,
      encounter,
      heroClass: getHeroClass(run.classId),
      heroHealth: run.currentHealth,
      heroMaxHealthBonus: run.maxHealthBonus,
      heroDamageBonusPct: run.damageBonusPct,
      heroShield: run.shield,
      codex: run.ownedRules,
      activeRuleIds: run.activeRuleIds,
      ink: run.ink,
      maxInk: run.maxInk,
      rewriteCostMultiplierPct: run.rewriteCostMultiplierPct,
      difficulty: run.difficulty,
    });
    this.lastEventSequence = 0;
    this.accumulator = 0;
    this.combatRecorded = false;
    this.paused = false;
    this.rewriteSuspendedCombat = false;
    this.screen = "combat";
    this.view.setArenaTheme(encounter.arenaTheme, encounter.chapter);
    this.view.sync(this.combat.getSnapshot());
  }

  private finishNonCombatRoom(message: string): void {
    const run = this.run;
    if (!run) return;
    const outcome = finishRoom(run);
    if (outcome === "victory") {
      this.completeRun(true);
      return;
    }
    this.screen = "map";
    this.showMessage(message);
    saveRun(run);
    this.emitSnapshot();
  }

  private completeRun(victory: boolean): void {
    const run = this.run;
    if (!run) return;
    if (this.combat) this.recordCombatOnce();
    updateMetaAfterRun(this.meta, run, victory);
    saveMeta(this.meta);
    saveRun(undefined);
    this.screen = "run-end";
    this.showMessage(
      victory ? "L’Auteur a perdu le dernier mot." : "Le Codex se referme, mais conserve la cicatrice.",
    );
    this.leaveCombatView();
    this.emitSnapshot();
  }

  private recordCombatOnce(): void {
    if (this.combatRecorded || !this.combat || !this.run) return;
    recordCombatResult(this.run, this.combat.getResult());
    this.combatRecorded = true;
    saveRun(this.run);
  }

  private leaveCombatView(clear = true): void {
    if (clear) this.combat = undefined;
    this.rewriteSuspendedCombat = false;
    this.paused = false;
    this.view.clearCombat();
  }

  private readonly frame = (timestamp: number): void => {
    if (this.disposed) return;
    const deltaSeconds =
      this.lastFrameTime === 0 ? 0 : Math.min(0.1, (timestamp - this.lastFrameTime) / 1000);
    this.lastFrameTime = timestamp;
    this.accumulator += deltaSeconds * this.settings.gameSpeed;
    const tickDuration = 1 / 20;
    let stepped = false;

    while (this.combat && this.accumulator >= tickDuration) {
      this.combat.step();
      this.accumulator -= tickDuration;
      stepped = true;
    }

    if (this.combat && stepped) {
      const events = this.combat.getEventsSince(this.lastEventSequence);
      if (events.length > 0) {
        const last = events.at(-1);
        if (last) this.lastEventSequence = last.sequence;
        this.view.handleEvents(events);
        this.audio.handleEvents(events);
      }
      const snapshot = this.combat.getSnapshot();
      this.view.sync(snapshot);
      if (snapshot.status === "victory" || snapshot.status === "defeat") this.recordCombatOnce();
      this.emitSnapshot();
    }

    this.view.render(deltaSeconds);
    this.animationFrame = requestAnimationFrame(this.frame);
  };

  private showMessage(message: string): void {
    this.message = message;
    this.messageId += 1;
  }

  private clearMessage(): void {
    this.message = undefined;
  }

  private emitSnapshot(): void {
    const snapshot: RuntimeSnapshot = {
      screen: this.screen,
      previousScreen: this.previousScreen,
      run: this.run ? structuredClone(this.run) : undefined,
      combat: this.combat?.getSnapshot(),
      meta: structuredClone(this.meta),
      settings: { ...this.settings },
      classDefinitions: HERO_CLASSES,
      ruleDefinitions: RULES,
      rewardOptions: structuredClone(this.rewardOptions),
      shopOffers: structuredClone(this.shopOffers),
      currentEvent: this.currentEvent ? structuredClone(this.currentEvent) : undefined,
      mapBranches: this.run ? generateBranchPreviews(this.run).map((branch) => structuredClone(branch)) : [],
      message: this.message,
      messageId: this.messageId,
      paused: this.paused,
    };
    this.onSnapshot(snapshot);
  }
}
