import { create } from "zustand";
import type { GameRuntime } from "../app/GameRuntime";
import type { RuntimeSnapshot } from "../domain/types";

interface GameUiState {
  runtime?: GameRuntime;
  snapshot?: RuntimeSnapshot;
  optionsOpen: boolean;
  rewriteOpen: boolean;
  selectedRuleIndexes: number[];
  setRuntime: (runtime?: GameRuntime) => void;
  setSnapshot: (snapshot: RuntimeSnapshot) => void;
  setOptionsOpen: (open: boolean) => void;
  setRewriteOpen: (open: boolean) => void;
  toggleRuleSelection: (index: number) => void;
  clearRuleSelection: () => void;
}

export const useGameStore = create<GameUiState>((set) => ({
  optionsOpen: false,
  rewriteOpen: false,
  selectedRuleIndexes: [],
  setRuntime: (runtime) => set({ runtime }),
  setSnapshot: (snapshot) => set({ snapshot }),
  setOptionsOpen: (optionsOpen) => set({ optionsOpen }),
  setRewriteOpen: (rewriteOpen) => set({ rewriteOpen, selectedRuleIndexes: rewriteOpen ? [] : [] }),
  toggleRuleSelection: (index) =>
    set((state) => {
      if (state.selectedRuleIndexes.includes(index)) {
        return { selectedRuleIndexes: state.selectedRuleIndexes.filter((value) => value !== index) };
      }
      if (state.selectedRuleIndexes.length >= 2) return { selectedRuleIndexes: [index] };
      return { selectedRuleIndexes: [...state.selectedRuleIndexes, index] };
    }),
  clearRuleSelection: () => set({ selectedRuleIndexes: [] })
}));
