import type { EventEnvelope, GameSettings } from "../domain/types";

export class AudioSystem {
  private context?: AudioContext;
  private master?: GainNode;
  private settings: GameSettings;

  public constructor(settings: GameSettings) {
    this.settings = settings;
  }

  public updateSettings(settings: GameSettings): void {
    this.settings = settings;
    if (this.master) this.master.gain.value = settings.masterVolume * settings.effectsVolume;
  }

  public async unlock(): Promise<void> {
    if (!this.context) {
      this.context = new AudioContext();
      this.master = this.context.createGain();
      this.master.gain.value = this.settings.masterVolume * this.settings.effectsVolume;
      this.master.connect(this.context.destination);
    }
    if (this.context.state === "suspended") await this.context.resume();
  }

  public handleEvents(events: EventEnvelope[]): void {
    if (!this.context || !this.master || this.settings.masterVolume <= 0) return;
    for (const event of events) {
      if (event.type === "DamageDealt") this.tone(Boolean(event.payload.critical) ? 220 : 120, 0.045, "square", Boolean(event.payload.critical) ? 0.09 : 0.035);
      if (event.type === "ExplosionCreated") this.sweep(90, 38, 0.24, 0.11);
      if (event.type === "StatusApplied") {
        const status = String(event.payload.status);
        this.tone(status === "freeze" ? 720 : status === "poison" ? 330 : 480, 0.09, "sine", 0.035);
      }
      if (event.type === "RuleTriggered") this.tone(620, 0.075, "triangle", 0.045);
      if (event.type === "RewriteUsed") this.sweep(240, 880, 0.32, 0.08);
      if (event.type === "EnemyKilled") this.sweep(160, 70, 0.16, 0.055);
      if (event.type === "CombatEnded") this.sweep(String(event.payload.result) === "victory" ? 280 : 150, String(event.payload.result) === "victory" ? 760 : 55, 0.7, 0.1);
    }
  }

  public dispose(): void {
    void this.context?.close();
    this.context = undefined;
    this.master = undefined;
  }

  private tone(frequency: number, duration: number, type: OscillatorType, volume: number): void {
    const context = this.context;
    const master = this.master;
    if (!context || !master) return;
    const oscillator = context.createOscillator();
    const gain = context.createGain();
    oscillator.type = type;
    oscillator.frequency.value = frequency;
    gain.gain.setValueAtTime(volume, context.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.0001, context.currentTime + duration);
    oscillator.connect(gain);
    gain.connect(master);
    oscillator.start();
    oscillator.stop(context.currentTime + duration);
  }

  private sweep(from: number, to: number, duration: number, volume: number): void {
    const context = this.context;
    const master = this.master;
    if (!context || !master) return;
    const oscillator = context.createOscillator();
    const gain = context.createGain();
    oscillator.type = "sawtooth";
    oscillator.frequency.setValueAtTime(from, context.currentTime);
    oscillator.frequency.exponentialRampToValueAtTime(Math.max(1, to), context.currentTime + duration);
    gain.gain.setValueAtTime(volume, context.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.0001, context.currentTime + duration);
    oscillator.connect(gain);
    gain.connect(master);
    oscillator.start();
    oscillator.stop(context.currentTime + duration);
  }
}
